const localStorage={getItem:k=>k==='mavon-finance-live-v1'?JSON.stringify(input):null,setItem(){}};
'use strict';
const DEMO_MODE=false;
const $=s=>document.querySelector(s),fmt=n=>new Intl.NumberFormat('fa-IR').format(n),money=n=>fmt(n)+' ریال',esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),uid=()=>crypto.randomUUID?crypto.randomUUID():Array.from(crypto.getRandomValues(new Uint8Array(16)),b=>b.toString(16).padStart(2,'0')).join(''),day=()=>new Date().toISOString().slice(0,10),pdate=s=>new Date(s+'T12:00:00').toLocaleDateString('fa-IR'),KEY=DEMO_MODE?'mavon-finance-split-demo-v1':'mavon-finance-live-v1';
let state,page='dashboard',query='';
const seed=()=>({schemaVersion:1,demo:true,products:[{id:'p1',code:'BL-1020',name:'ساعت بلموند کلاسیک',brand:'BELMOND',price:8500000,cost:6100000,opening:24},{id:'p2',code:'ES-6518',name:'ساعت اسنس صفحه سرمه‌ای',brand:'ESSENCE',price:6200000,cost:4300000,opening:18},{id:'p3',code:'LC-201',name:'ساعت لاکوست اسپرت',brand:'LACOSTE',price:12800000,cost:9100000,opening:3},{id:'p4',code:'CAT-141',name:'ساعت کَت بند چرمی',brand:'CAT',price:7900000,cost:5500000,opening:12}],parties:[{id:'c1',name:'گالری ساعت آریا',phone:'09121234567',type:'customer',opening:12500000},{id:'c2',name:'محمد رضایی',phone:'09125556677',type:'customer',opening:0},{id:'s1',name:'بازرگانی زمان',phone:'02188776655',type:'supplier',opening:18000000}],invoices:[],payments:[],checks:[]});
const emptySeed=()=>normalizeData({schemaVersion:1,currency:'IRR',checkAccounting:'receipt',warehouseSchema:1,demo:false,products:[],parties:[],invoices:[],payments:[],checks:[],returns:[],staff:[],audit:[]});
try{const raw=localStorage.getItem(KEY);let loaded=normalizeData(raw?JSON.parse(raw):(DEMO_MODE?demoSeed():emptySeed()));if(loaded.schemaVersion!==1)throw Error('نسخه داده پشتیبانی نمی‌شود');if(loaded.currency!=='IRR'){state=normalizeData(convertToIRR(loaded));if(raw){state.audit.push({id:uid(),entity:'system',entityId:'currency',action:'update',at:new Date().toISOString(),user:currentActor(),changes:[{field:'currency',before:'IRT',after:'IRR'}],snapshot:{name:'تبدیل مبالغ به ریال؛ ارزش مالی ثابت'}});localStorage.setItem(KEY+'-before-IRR',raw);localStorage.setItem(KEY,JSON.stringify(state))}}else state=loaded;if(state.checkAccounting!=='receipt'){const prior=JSON.stringify(state);state.checkAccounting='receipt';if(raw){state.audit.push({id:uid(),entity:'system',entityId:'check-policy',action:'update',at:new Date().toISOString(),user:currentActor(),changes:[{field:'note',before:'کسر هنگام وصول',after:'کسر هنگام دریافت؛ وصول بدون کسر مجدد'}],snapshot:{name:'تغییر مبنای حسابداری چک به دریافت'}});localStorage.setItem(KEY+'-before-check-receipt',prior);localStorage.setItem(KEY,JSON.stringify(state))}}if(state.warehouseSchema!==1){state.warehouseSchema=1;if(raw){localStorage.setItem(KEY+'-before-warehouses',raw);state.audit.push({id:uid(),entity:'system',entityId:'warehouses',action:'update',at:new Date().toISOString(),user:currentActor(),changes:[{field:'note',before:null,after:'انتساب موجودی و اسناد قبلی به انبار اصلی؛ تعداد و ارزش ثابت'}],snapshot:{name:'فعال‌سازی انبارهای مستقل'}});localStorage.setItem(KEY,JSON.stringify(state))}}}catch(e){document.body.innerHTML='<p style="padding:30px">بارگذاری یا تبدیل ریالی انجام نشد؛ اطلاعات اصلی حفظ شده است. '+esc(e.message)+'</p>';throw e}
function documentNumber(prefix,sequence){return prefix+String(sequence)+(typeof window!=='undefined'&&window.MavonSync?.enabled?'-'+window.MavonSync.device:'')}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));if(typeof window!=='undefined')window.MavonSync?.changed();return true}catch(e){toast('ذخیره انجام نشد؛ فضای ذخیره مرورگر را بررسی کنید.');return false}}
function previousCommit(fn){const before=JSON.stringify(state);fn();if(!save()){state=JSON.parse(before);return false}render();return true}
function toast(s){$('.toast')?.remove();let e=document.createElement('div');e.className='toast';e.textContent=s;document.body.append(e);setTimeout(()=>e.remove(),4500)}
function old050Stock(id){return state.products.find(p=>p.id===id).opening+stockMovements(id).reduce((s,m)=>s+m.delta,0)}
function total(i){return i.items.reduce((s,l)=>s+l.qty*l.price,0)-i.discount}
function old041Balance(id){const p=state.parties.find(p=>p.id===id);return p.opening+state.invoices.filter(i=>i.partyId===id).reduce((s,i)=>s+total(i)-i.paid,0)-state.payments.filter(x=>x.partyId===id).reduce((s,x)=>s+x.amount,0)-state.returns.filter(r=>r.partyId===id).reduce((s,r)=>s+returnTotal(r)-r.paid,0)}
const navs=[['dashboard','خانه','M3 10 12 3l9 7v11H3Z M9 21v-8h6v8'],['accounts','حساب مشتریان','M4 4h16v16H4Z M8 8h8 M8 12h5'],['details','گروه‌های تفصیلی','M3 6h7l2 3h9v12H3Z'],['finance','امور مالی','M3 7h18v13H3Z M3 11h18 M6 16h3'],['warehouse','انبار','M3 7 12 2l9 5v10l-9 5-9-5Z M3 7l9 5 9-5 M12 12v10'],['trade','بازرگانی و فروش','M6 3h12v19l-3-2-3 2-3-2-3 2Z M9 8h6 M9 12h6'],['access','دسترسی پرسنل','M12 2 3 6v6c0 5 9 10 9 10s9-5 9-10V6Z M8 12l3 3 5-6'],['history','تاریخچه عملیات','M4 4h16v16H4Z M8 8h8 M8 12h8 M8 16h5'],['settings','پشتیبان و تنظیمات','M4 4h16v16H4Z M8 4v6h8V4 M8 20v-6h8v6']];
function go(p){if(!can(p))return toast('این کاربر اجازه ورود به این بخش را ندارد.');page=DEMO_MODE&&p==='dashboard'?'splitDemo':p;query='';$('#globalSearch').value='';$('#sidebar').classList.remove('open');render()}
function buttons(){return '<button class="btn primary" onclick="invoiceForm(\'sale\')">＋ فاکتور فروش</button><button class="btn" onclick="invoiceForm(\'purchase\')">ثبت خرید</button>'}
function title(t,s,a=''){return `<div class="titlebar"><div><div class="eyebrow">MAVON / FINANCE</div><h1>${t}</h1><p>${s}</p></div><div class="actions">${a}</div></div>`}
function panel(t,b,a=''){return `<section class="panel"><div class="panelhead"><h2>${t}</h2>${a}</div>${b}</section>`}
function table(head,rows){return `<div class="tablewrap"><table><thead><tr>${head.map(h=>'<th>'+h+'</th>').join('')}</tr></thead><tbody>${rows||'<tr><td colspan="10"><div class="empty">هنوز موردی ثبت نشده است.</div></td></tr>'}</tbody></table></div>`}
function render(){if(!can(page)){page='dashboard';query=''}const profile=$('.profile b');if(profile)profile.textContent=currentActor().name;const parent=moduleOf(page);$('#nav').innerHTML=navs.filter(([id])=>can(id)).map(([id,name,path],n)=>`${n===6?'<div class="navlabel">مدیریت سیستم</div>':''}<button onclick="go('${id}')" class="${parent===id?'active':''}"><svg viewBox="0 0 24 24"><path d="${path}"/></svg>${name}</button>`).join('');const views={dashboard,products,parties,invoices,payments,checks,reports,settings,accounts,details,finance,warehouse,trade,access,groups,cardex,returns,suppliers,history,splitDemo,warehouses,inventory,transfers,pricing,cashflow};const sub=modulePages[parent];$('#content').innerHTML=`<div class="actions exportbar" style="margin-bottom:18px"><button class="btn gold" onclick="exportCurrent()">خروجی اکسل این بخش</button>${can('settings')?'<button class="btn" onclick="exportAllExcel()">خروجی کامل اکسل</button>':''}</div>`+(page!=='dashboard'&&sub?`<div class="sectiontabs">${sub.map(([id,label])=>`<button class="${page===id?'selected':''}" onclick="go('${id}')">${label}</button>`).join('')}</div>`:'')+views[page]()+`<div class="footnote"><span>ماوون؛ حساب روشن، تصمیم بهتر.</span><span>${state.demo?'فضای کاری':'اطلاعات این مرورگر'} · نسخه ۰.۷.۲</span></div>`;}
function invoiceRows(list){return list.map(i=>`<tr><td><button class="link" onclick="viewInvoice('${i.id}')">${esc(i.number)}</button></td><td>${esc(state.parties.find(p=>p.id===i.partyId)?.name)}</td><td>${pdate(i.date)}</td><td><span class="badge ${i.type==='sale'?'ok':'warn'}">${i.type==='sale'?'فروش':'خرید'}</span></td><td>${money(total(i))}</td><td><span class="badge ${invoiceOutstanding(i)<=0?'ok':'bad'}">${invoiceOutstanding(i)<=0?'تسویه شده':'اعتباری'}</span></td><td><button class="btn small" onclick="viewInvoice('${i.id}')">مشاهده و چاپ</button> ${editAction('invoices',i.id)}</td></tr>`).join('')}
function legacyDashboard(){const sales=state.invoices.filter(i=>i.type==='sale').reduce((s,i)=>s+total(i),0),receivable=state.parties.filter(p=>p.type==='customer').reduce((s,p)=>s+Math.max(0,balance(p.id)),0),payable=state.parties.filter(p=>p.type==='supplier').reduce((s,p)=>s+Math.max(0,balance(p.id)),0),inv=state.products.reduce((s,p)=>s+stock(p.id)*p.cost,0);let vals=[['مجموع فروش',sales,'تمام فاکتورهای فروش','↗'],['ارزش موجودی انبار',inv,fmt(state.products.reduce((s,p)=>s+stock(p.id),0))+' عدد کالا در انبار','▣'],['مطالبات از مشتریان',receivable,'مانده حساب مشتریان','↙'],['بدهی به تأمین‌کنندگان',payable,'مانده حساب تأمین‌کنندگان','↗']];let days=Array.from({length:7},(_,i)=>{let d=new Date();d.setDate(d.getDate()-6+i);return d.toISOString().slice(0,10)}),chart=days.map(d=>({d,s:state.invoices.filter(i=>i.date===d&&i.type==='sale').reduce((a,i)=>a+total(i),0),b:state.invoices.filter(i=>i.date===d&&i.type==='purchase').reduce((a,i)=>a+total(i),0)})),max=Math.max(1,...chart.flatMap(x=>[x.s,x.b]));let pending=state.checks.filter(c=>c.status==='pending').sort((a,b)=>a.date.localeCompare(b.date)).slice(0,3);return title('نمای کلی کسب‌وکار','معین، به فضای مالی ماوون خوش آمدی.',buttons())+(state.demo?'<div class="notice">این فضای کاری با چند کالای نمونه آماده شده است. اطلاعات روی همین مرورگر ذخیره می‌شود؛ برای اتصال این دستگاه، دکمه «همگام‌سازی» بالای صفحه را بزنید.</div>':'')+`<div class="stats">${vals.map(([t,v,n,ic])=>`<div class="stat"><div class="stathead">${t}<span class="ico">${ic}</span></div><div class="value">${fmt(v)}<span class="unit">ریال</span></div><div class="statnote">${n}</div></div>`).join('')}</div><div class="grid">${panel('روند خرید و فروش',`<div class="panelbody"><div class="legend"><span><i></i>فروش</span><span><i class="goldi"></i>خرید</span><span style="margin-right:auto;color:#999">۷ روز اخیر · ریال</span></div><div class="chart">${chart.map(x=>`<div class="bargrp" title="${pdate(x.d)} | فروش ${money(x.s)} | خرید ${money(x.b)}"><div class="bar" style="height:${x.s/max*95}%"></div><div class="bar buy" style="height:${x.b/max*95}%"></div></div>`).join('')}</div><div class="labels">${days.map(d=>'<span>'+new Date(d+'T12:00:00').toLocaleDateString('fa-IR',{weekday:'short'})+'</span>').join('')}</div>${!state.invoices.length?'<div class="helper" style="text-align:center;margin-top:17px">با ثبت اولین فاکتور، نمودار شما شکل می‌گیرد.</div>':''}</div>`)}${panel('چک‌های پیش رو',`<div class="panelbody">${pending.map(c=>`<div class="checkrow"><div><b>${esc(c.bank)}</b><div class="sub">${esc(state.parties.find(p=>p.id===c.partyId)?.name)}</div></div><div style="text-align:left"><b>${money(c.amount)}</b><div class="sub">${pdate(c.date)}</div></div></div>`).join('')||'<div class="empty">چکی در انتظار سررسید ندارید.<br><button class="btn small" style="margin-top:15px" onclick="checkForm()">＋ ثبت اولین چک</button></div>'}</div>`,'<button class="link" onclick="go(\'checks\')">همه چک‌ها ←</button>')}</div>`+panel('آخرین فاکتورها',table(['شماره فاکتور','طرف حساب','تاریخ','نوع','مبلغ کل','وضعیت',''],invoiceRows([...state.invoices].reverse().slice(0,5))),'<button class="link" onclick="go(\'invoices\')">مشاهده همه ←</button>')+`<div style="margin-top:22px">${panel('موجودی نیازمند توجه',table(['کالا','رفرنس','موجودی',''],state.products.filter(p=>stock(p.id)<=3).map(p=>`<tr><td>${esc(p.name)}</td><td class="ref">${esc(p.code)}</td><td><span class="badge warn">${fmt(stock(p.id))} عدد</span></td><td><button class="link" onclick="invoiceForm('purchase')">ثبت خرید ←</button></td></tr>`).join('')))}</div>`}
function products(){const list=state.products.filter(p=>(p.name+p.code+p.brand).toLowerCase().includes(query.toLowerCase()));return title('تعریف کالا','تعریف و اصلاح مشخصات کالا، به‌صورت تکی یا با اکسل.',`<button class="btn" onclick="importForm()">تعریف کالا با اکسل</button><button class="btn primary" onclick="productForm()">＋ تعریف کالای جدید</button>`)+`<div class="toolbar"><input placeholder="جست‌وجوی نام یا رفرنس…" value="${esc(query)}" oninput="filterPage(this.value)"><span class="helper">${fmt(list.length)} کالای تعریف‌شده</span></div>`+panel('کالاهای تعریف‌شده',table(['نام کالا','رفرنس','برند',''],list.map(p=>`<tr><td><b>${esc(p.name)}</b></td><td class="ref">${esc(p.code)}</td><td>${esc(p.brand)}</td><td>${can('warehouse','edit')?`<button class="btn small" onclick="productForm('${p.id}')">اصلاح مشخصات</button>`:''}</td></tr>`).join('')))}
function legacyParties(){let list=state.parties.filter(p=>(p.name+p.phone).includes(query));return title('مشتریان و تأمین‌کنندگان','حساب هر طرف معامله، شفاف و در دسترس.',`<button class="btn primary" onclick="partyForm()">＋ طرف حساب جدید</button>`)+`<div class="toolbar"><input placeholder="جست‌وجوی نام یا تلفن…" value="${esc(query)}" oninput="filterPage(this.value)"></div>`+panel('طرف‌های حساب',table(['نام','نوع','تلفن','مانده حساب',''],list.map(p=>`<tr><td><b>${esc(p.name)}</b></td><td><span class="badge ${p.type==='customer'?'ok':'warn'}">${p.type==='customer'?'مشتری':'تأمین‌کننده'}</span></td><td dir="ltr" style="text-align:right">${esc(p.phone)}</td><td>${money(Math.abs(balance(p.id)))}<div class="sub">${balance(p.id)>=0?(p.type==='customer'?'بدهکار به ما':'طلبکار از ما'):(p.type==='customer'?'بستانکار از ما':'بدهکار به ما')}</div></td><td><button class="btn small" onclick="ledger('${p.id}')">ریز حساب</button> <button class="link" onclick="partyForm('${p.id}')">ویرایش</button></td></tr>`).join('')))}
function invoices(){return title('فاکتورهای خرید و فروش','ثبت معامله، تغییر موجودی و گردش حساب به‌صورت هم‌زمان.',buttons()+`<button class="btn gold" onclick="addMainExample()">ثبت فاکتور نمونه</button>`)+(DEMO_MODE?'':mainExampleNotice())+panel('همه فاکتورها',table(['شماره فاکتور','طرف حساب','تاریخ','نوع','مبلغ کل','وضعیت',''],invoiceRows([...state.invoices].reverse().filter(i=>(i.number+state.parties.find(p=>p.id===i.partyId)?.name).includes(query)))))}
function previousPayments(){return title('دریافت و پرداخت','ثبت پرداخت‌ها و دریافت‌های مستقل از فاکتور.',`<button class="btn primary" onclick="paymentForm()">＋ ثبت تراکنش</button>`)+panel('گردش وجوه',table(['طرف حساب','نوع','تاریخ','مبلغ','شرح'],[...state.payments].reverse().map(p=>{const party=state.parties.find(x=>x.id===p.partyId);return `<tr><td>${esc(party.name)}</td><td><span class="badge ${party.type==='customer'?'ok':'warn'}">${party.type==='customer'?'دریافت':'پرداخت'}</span></td><td>${pdate(p.date)}</td><td>${money(p.amount)}</td><td>${esc(p.note)}</td></tr>`}).join('')))}
function previousChecks(){return title('مدیریت چک‌ها','پیگیری چک‌های دریافتی و پرداختی تا وصول یا برگشت.',`<button class="btn primary" onclick="checkForm()">＋ چک جدید</button>`)+`<div class="notice">ثبت چک به‌تنهایی حساب را تسویه نمی‌کند. با انتخاب «وصول شد»، دریافت یا پرداخت متناظر به‌صورت خودکار ثبت می‌شود.</div>`+panel('دفتر چک‌ها',table(['شماره / بانک','طرف حساب','نوع','سررسید','مبلغ','وضعیت'],state.checks.map(c=>`<tr><td>${esc(c.number)}<div class="sub">${esc(c.bank)}</div></td><td>${esc(state.parties.find(p=>p.id===c.partyId)?.name)}</td><td>${c.type==='received'?'دریافتی':'پرداختی'}</td><td>${pdate(c.date)}</td><td>${money(c.amount)}</td><td>${c.status==='cleared'?'<span class="badge ok">وصول شده</span>':`<select aria-label="وضعیت چک" onchange="changeCheck('${c.id}',this.value)"><option value="pending" ${c.status==='pending'?'selected':''}>در انتظار</option><option value="returned" ${c.status==='returned'?'selected':''}>برگشتی</option><option value="cleared">وصول شد</option></select>`}</td></tr>`).join('')))}
function reports(){return title('گزارش‌ها و ریز حساب','یک طرف حساب را برای مشاهده گردش کامل انتخاب کن.')+panel('صورت حساب طرف‌های معامله',`<div class="panelbody"><div class="fields">${state.parties.map(p=>`<button class="btn" style="justify-content:space-between;padding:20px" onclick="ledger('${p.id}')"><b>${esc(p.name)}</b><span>${money(balance(p.id))} ←</span></button>`).join('')}</div>${!state.parties.length?'<div class="empty">ابتدا طرف حساب تعریف کنید.</div>':''}</div>`)}
function settings(){return `<div class="actions" style="margin-bottom:20px"><button class="btn" onclick="operatorForm()">اسم المستخدم المحلي: ${esc(currentActor().name)}</button><button class="btn" onclick="go('history')">تاريخچه تمام عمليات</button></div>`+title('پشتیبان و تنظیمات','اطلاعات قابل انتقال، با ساختار نسخه‌بندی‌شده.')+`<div class="notice">اطلاعات ابتدا روی دستگاه ذخیره می‌شود. برای اتصال سرور و مدیریت کاربران واقعی، دکمه همگام‌سازی بالای صفحه را بزنید. هر ارسال موفق روی سرور نسخه پشتیبان دارد. برای حسابداری واقعی، نسخه عملیاتی باید تکمیل و آزموده شود.</div><div class="grid">${panel('حفاظت از اطلاعات',`<div class="panelbody"><p>از داده‌های فعلی فایل پشتیبان بگیر یا پشتیبان قبلی را برگردان. قبل از بازیابی، پشتیبان اطلاعات فعلی به‌صورت خودکار دانلود می‌شود.</p><div class="actions" style="margin-top:22px"><button class="btn primary" onclick="backup()">دریافت پشتیبان JSON</button><button class="btn" onclick="document.getElementById('restore').click()">بازیابی پشتیبان</button><input id="restore" type="file" accept=".json" hidden onchange="restoreFile(this.files[0])"></div></div>`)}${panel('اطلاعات نسخه',`<div class="panelbody"><div class="kpirow"><span>نسخه نرم‌افزار</span><b>۰.۷.۲</b></div><div class="kpirow"><span>ساختار داده</span><b>v1</b></div><div class="kpirow"><span>محل ذخیره</span><b>همین مرورگر</b></div><div class="kpirow"><span>همگام‌سازی</span><span class="badge warn">هنوز فعال نیست</span></div></div>`)}</div>${state.demo?panel('شروع با اطلاعات خودت',`<div class="panelbody"><p>با حذف داده‌های نمونه، فضای خالی برای ثبت اطلاعات خودت آماده می‌شود. ابتدا پشتیبان دانلود خواهد شد.</p><button class="btn" style="margin-top:17px" onclick="clearDemo()">حذف داده‌های نمونه و شروع</button></div>`):''}`}
function filterPage(v){query=v;let pos=document.activeElement.selectionStart;render();const e=$('.toolbar input');if(e){e.focus();e.setSelectionRange(pos,pos)}}
$('#globalSearch').addEventListener('input',e=>{query=e.target.value;if(!['products','parties','invoices'].includes(page))page='products';render()});
function show(t,body){$('#modal').classList.remove('wide-dialog');$('#modalTitle').textContent=t;$('#modalBody').innerHTML=body;if(typeof document.getElementById==='function'){document.getElementById('exportModalButton')?.remove();if(body.includes('<table')&&!body.includes('<form')){const button=document.createElement('button');button.id='exportModalButton';button.type='button';button.className='btn small gold';button.textContent='خروجی اکسل';button.onclick=exportModal;document.querySelector('.modalhead').append(button)}}if(!$('#modal').open)$('#modal').showModal()}
function field(label,name,value='',type='text',extra=''){if(type==='date')return dateField(label,name,value,extra);const numeric=type==='number';return `<label>${label}<input name="${name}" type="${numeric?'text':type}" value="${esc(numeric?grouped(value):value)}" ${numeric?'data-numeric inputmode="numeric"':''} ${extra}></label>`}
function formWrap(body,submit){return `<form class="formbody" onsubmit="event.preventDefault();if(!prepareNumericForm(this))return false;${submit};reformatForm(this);return false">${body}<div class="formfoot"><button class="btn" type="button" onclick="modal.close()">انصراف</button><button class="btn primary" type="submit">ذخیره اطلاعات</button></div></form>`}
function productForm(id){const p=state.products.find(p=>p.id===id)||{};show(id?'ویرایش کالا':'تعریف کالای جدید',formWrap(`<div class="fields">${field('نام کالا','name',p.name,'text','required maxlength="120"')}${field('رفرنس / کد یکتا','code',p.code,'text','required maxlength="60"')}${field('برند','brand',p.brand)}${warehouseField('openingWarehouseId',p.openingWarehouseId||mainWarehouse(),'انبار موجودی اولیه')}${field('موجودی اولیه','opening',p.opening||0,'number','required min="0" step="1" '+'')}${field('قیمت خرید (ریال)','cost',p.cost||0,'number','required min="0" step="1" max="1000000000000"')}${field('قیمت فروش (ریال)','price',p.price||0,'number','required min="0" step="1" max="1000000000000"')}</div>${id?'<p class="helper" style="margin-top:15px">تغییر موجودی اولیه کنترل و در تاریخچه ثبت می‌شود. قیمت فاکتورهای قبلی با ویرایش کالا تغییر نمی‌کند.</p>':''}`,`submitProduct(this,'${id||''}')`));if(id)$('#modalBody').insertAdjacentHTML('beforeend',recordMeta('products',id))}
function submitProduct(form,id){const d=Object.fromEntries(new FormData(form));if(state.products.some(p=>p.code===d.code.trim()&&p.id!==id))return toast('این رفرنس قبلاً ثبت شده است.');const p={id:id||uid(),name:d.name.trim(),code:d.code.trim(),brand:d.brand.trim(),openingWarehouseId:d.openingWarehouseId,cost:+d.cost,price:+d.price,opening:+d.opening};if(!p.name||!p.code)return toast('نام و رفرنس را وارد کنید.');if(commit(()=>{if(id)Object.assign(state.products.find(p=>p.id===id),p);else state.products.push(p);validateFinancialState()})){$('#modal').close();toast('کالا ذخیره شد.')}}
function partyForm(id){const p=state.parties.find(p=>p.id===id)||{};show(id?'ویرایش طرف حساب':'طرف حساب جدید',formWrap(`<div class="fields">${field('نام شخص یا مجموعه','name',p.name,'text','required maxlength="120"')}<label>نوع طرف حساب<select name="type" onchange="partyGroupOptions(this.value)" ${id?'disabled':''}><option value="customer">مشتری</option><option value="supplier" ${p.type==='supplier'?'selected':''}>تأمین‌کننده</option></select></label><label>گروه تفصیلی<select name="groupId">${state.groups.filter(g=>!p.type||g.type===p.type).map(g=>`<option value="${g.id}" ${p.groupId===g.id?'selected':''}>${esc(g.name)}</option>`).join('')}</select></label>${field('شماره تماس','phone',p.phone,'tel','maxlength="25"')}${field('استان','province',p.province,'text','maxlength="80"')}${field('شهر','city',p.city,'text','maxlength="80"')}${field('نشانی کامل','address',p.address,'text','maxlength="500"')}${field('مانده اولیه (ریال)','opening',p.opening||0,'number','required step="1" '+'')}</div><div class="helper" style="margin-top:12px">مانده مثبت: بدهی مشتری به شما یا طلب تأمین‌کننده از شما. مانده منفی: برعکس.</div>`,`submitParty(this,'${id||''}')`));partyGroupOptions(p.type||'customer',p.groupId);if(id)$('#modalBody').insertAdjacentHTML('beforeend',recordMeta('parties',id))}
function submitParty(form,id){let d=Object.fromEntries(new FormData(form));d.name=d.name.trim();if(!d.name)return toast('نام را وارد کنید.');const kind=id?state.parties.find(p=>p.id===id).type:d.type;if(!state.groups.some(g=>g.id===d.groupId&&g.type===kind))return toast('گروه تفصیلی متناسب انتخاب کنید.');if(commit(()=>{if(id)Object.assign(state.parties.find(p=>p.id===id),{name:d.name,phone:d.phone,province:d.province,city:d.city,address:d.address,groupId:d.groupId,opening:numCell(d.opening)});else state.parties.push({...d,id:uid(),opening:+d.opening});validateFinancialState()})){$('#modal').close();toast('طرف حساب ذخیره شد.')}}
let draftType='sale';
function old040InvoiceForm(type){if(!state.products.length)return toast('ابتدا یک کالا تعریف کنید.');const opts=state.parties.filter(p=>p.type===(type==='sale'?'customer':'supplier'));if(!opts.length){toast('ابتدا '+(type==='sale'?'مشتری':'تأمین‌کننده')+' تعریف کنید.');return partyForm()}draftType=type;show(type==='sale'?'فاکتور فروش جدید':'فاکتور خرید جدید',formWrap(`<div class="fields"><label>طرف حساب<select name="partyId" required>${opts.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select></label>${field('تاریخ سند (شمسی)','date',day(),'date','required')}</div><div style="margin-top:24px"><div class="helper" style="margin-bottom:8px">کالا / تعداد / قیمت واحد به ریال</div><div id="lines"></div><button type="button" class="btn small" onclick="addLine()">＋ افزودن ردیف</button></div><div class="fields" style="margin-top:22px">${field('تخفیف کل (ریال)','discount',0,'number','required min="0" step="1" oninput="calcDraft()"')}${field('پرداخت هم‌زمان (ریال)','paid',0,'number','required min="0" step="1"')}</div><div class="previewtotal" id="draftTotal"></div>`,`submitInvoice(this)`));addLine()}
function old040AddLine(){let div=document.createElement('div');div.className='lineitem';div.innerHTML=`<select aria-label="کالا" onchange="lineProduct(this)">${state.products.map(p=>`<option value="${p.id}">${esc(p.name)} (${esc(p.code)})</option>`).join('')}</select><input aria-label="تعداد" class="qty" type="number" min="1" step="1" value="1" required oninput="calcDraft()"><input aria-label="قیمت واحد" class="price" type="number" min="0" max="1000000000000" step="1" required oninput="calcDraft()"><button class="close" type="button" aria-label="حذف ردیف" onclick="this.parentElement.remove();calcDraft()">×</button>`;$('#lines').append(div);lineProduct(div.querySelector('select'))}
function old040LineProduct(select){let p=state.products.find(p=>p.id===select.value);select.parentElement.querySelector('.price').value=draftType==='sale'?p.price:p.cost;calcDraft()}
function old040DraftLines(){return [...document.querySelectorAll('.lineitem')].map(l=>{let p=state.products.find(p=>p.id===l.querySelector('select').value);return {productId:p.id,name:p.name,code:p.code,qty:+l.querySelector('.qty').value,price:+l.querySelector('.price').value}})}
