function pre040SubmitInvoice(form){const d=Object.fromEntries(new FormData(form)),items=draftLines();if(!items.length)return toast('حداقل یک ردیف کالا لازم است.');if(items.some(l=>!Number.isSafeInteger(l.qty)||l.qty<1||!Number.isSafeInteger(l.price)||l.price<0))return toast('تعداد و قیمت معتبر وارد کنید.');const amount=items.reduce((s,l)=>s+l.qty*l.price,0)-+d.discount;if(!Number.isSafeInteger(amount)||amount<0||+d.paid>amount)return toast('تخفیف یا پرداخت از مبلغ فاکتور بیشتر است.');if(draftType==='sale'){for(const id of new Set(items.map(l=>l.productId)))if(items.filter(l=>l.productId===id).reduce((s,l)=>s+l.qty,0)>stock(id))return toast('موجودی '+state.products.find(p=>p.id===id).name+' کافی نیست.')}const i={id:uid(),number:documentNumber(draftType==='sale'?'F-':'P-',state.invoices.length+1001),type:draftType,partyId:d.partyId,date:d.date,discount:+d.discount,paid:+d.paid,items,createdAt:new Date().toISOString()};if(commit(()=>state.invoices.push(i))){$('#modal').close();toast('فاکتور ثبت شد؛ موجودی و حساب به‌روز شد.');viewInvoice(i.id)}}
function invoiceHTML(i){const p=state.parties.find(p=>p.id===i.partyId);return `<h1>ماوون | فاکتور ${i.type==='sale'?'فروش':'خرید'}</h1><div class="printmeta" style="line-height:2.3;margin:20px 0">طرف حساب: <b>${esc(p.name)}</b><br>${esc([p.province,p.city,p.address].filter(Boolean).join('، '))}<br>شماره: ${esc(i.number)} · تاریخ: ${pdate(i.date)}<br>انبار: ${esc(warehouseName(i.warehouseId))}</div>${table(['رفرنس','شرح کالا','تعداد','فی (ریال)','مبلغ (ریال)'],i.items.map(l=>`<tr><td>${esc(l.code)}</td><td>${esc(l.name)}</td><td>${fmt(l.qty)}</td><td>${fmt(l.price)}</td><td>${fmt(l.qty*l.price)}</td></tr>`).join(''))}<div style="line-height:2.5;margin-top:20px">تخفیف: ${money(i.discount)}<br><b>مبلغ نهایی: ${money(total(i))}</b><br>پرداخت هم‌زمان: ${money(i.paid)}<br>تسویه‌های بعدی: ${money(invoiceLaterPaid(i))}<br>مانده این فاکتور: ${money(invoiceOutstanding(i))}</div><p style="margin-top:35px">امضا و مهر فروشنده __________________　 امضای خریدار __________________</p>`}
function viewInvoice(id){if(!can('trade'))return toast('اجازه مشاهده فاکتور ندارید.');const i=state.invoices.find(i=>i.id===id);show('جزئیات فاکتور',`<div class="formbody">${invoiceHTML(i)}${recordMeta('invoices',i.id)}${editAction('invoices',i.id)}<button class="btn primary" style="margin-top:25px" onclick="printInvoice('${id}')">چاپ / ذخیره PDF</button></div>`)}
function printInvoice(id){$('#printarea').innerHTML=invoiceHTML(state.invoices.find(i=>i.id===id));window.print()}
function old040PaymentForm(){if(!state.parties.length)return partyForm();show('ثبت دریافت یا پرداخت',formWrap(`<div class="fields"><label>طرف حساب<select name="partyId">${state.parties.map(p=>`<option value="${p.id}">${esc(p.name)} — ${p.type==='customer'?'دریافت از مشتری':'پرداخت به تأمین‌کننده'}</option>`).join('')}</select></label><label>روش پرداخت<select name="method"><option value="cash">نقدی</option><option value="bank">واریز / انتقال بانکی</option><option value="card">کارت‌خوان</option></select></label>${field('مبلغ (ریال)','amount','','number','required min="1" max="1000000000000" step="1"')}${field('تاریخ','date',day(),'date','required')}${field('شرح / شماره پیگیری','note','','text','maxlength="250"')}</div>`,`submitPayment(this)`))}
function old040SubmitPayment(form){const d=Object.fromEntries(new FormData(form));if(commit(()=>state.payments.push({...d,id:uid(),amount:+d.amount}))) {$('#modal').close();toast('تراکنش ثبت شد.')}}
function checkForm(){if(!state.parties.length)return partyForm();show('ثبت چک',formWrap(`<div class="fields"><label>طرف حساب<select name="partyId">${state.parties.map(p=>`<option value="${p.id}">${esc(p.name)} — ${p.type==='customer'?'دریافتی':'پرداختی'}</option>`).join('')}</select></label>${field('شماره چک / شناسه صیادی','number','','text','required maxlength="40"')}${field('نام بانک','bank','','text','required maxlength="80"')}${field('مبلغ (ریال)','amount','','number','required min="1" max="1000000000000" step="1"')}${field('سررسید','date',day(),'date','required')}</div>`,`submitCheck(this)`))}
function submitCheck(form){const d=Object.fromEntries(new FormData(form));if(state.checks.some(c=>c.number===d.number.trim()&&c.bank===d.bank.trim()))return toast('این چک قبلاً ثبت شده است.');const p=state.parties.find(p=>p.id===d.partyId);if(commit(()=>state.checks.push({...d,number:d.number.trim(),bank:d.bank.trim(),id:uid(),amount:+d.amount,type:p.type==='customer'?'received':'issued',status:'pending'}))){$('#modal').close();toast('چک ثبت شد.')}}
function previousChangeCheck(id,status){const c=state.checks.find(c=>c.id===id);if(status==='cleared'&&!confirm('وصول چک تأیید می‌شود؟ تراکنش تسویه به حساب اضافه خواهد شد.'))return render();commit(()=>{c.status=status;if(status==='cleared')state.payments.push({id:uid(),partyId:c.partyId,amount:c.amount,date:day(),note:'وصول چک '+c.number,checkId:id})});toast('وضعیت چک به‌روز شد.')}
function legacyLedger(id){const p=state.parties.find(p=>p.id===id);let rows=[{date:'0000',label:'مانده اول دوره',debit:p.opening,credit:0}];state.invoices.filter(i=>i.partyId===id).forEach(i=>rows.push({date:i.date,label:'فاکتور '+i.number,debit:total(i),credit:i.paid}));state.payments.filter(x=>x.partyId===id).forEach(x=>rows.push({date:x.date,label:x.note||'تراکنش',debit:0,credit:x.amount}));rows.sort((a,b)=>a.date.localeCompare(b.date));let b=0;let html=`<h2>ریز حساب ${esc(p.name)}</h2><p style="margin-top:12px">${p.type==='customer'?'مانده مثبت: بدهی مشتری به شما':'مانده مثبت: طلب تأمین‌کننده از شما'}</p>`+table(['تاریخ','شرح','افزایش مانده','کاهش مانده','مانده'],rows.map(r=>{b+=r.debit-r.credit;return `<tr><td>${r.date==='0000'?'—':pdate(r.date)}</td><td>${esc(r.label)}</td><td>${fmt(r.debit)}</td><td>${fmt(r.credit)}</td><td>${fmt(b)}</td></tr>`}).join(''))+`<div class="previewtotal">مانده نهایی: ${money(b)}</div>`;show('صورت حساب',`<div class="formbody">${html}<button class="btn primary" style="margin-top:22px" id="printLedger">چاپ ریز حساب</button></div>`);$('#printLedger').onclick=()=>{$('#printarea').innerHTML=html;window.print()}}
function download(name,text,type='application/json'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000)}
function backup(){download('mavon-backup-'+jalaliInput(day()).replace(/\//g,'-')+'.json',JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2))}
function legacyValidateBackup(d){if(d.schemaVersion!==1||!['products','parties','invoices','checks','payments'].every(k=>Array.isArray(d[k])))throw Error('ساختار پشتیبان معتبر نیست.');const ids=new Set();for(const k of ['products','parties','invoices','checks','payments'])for(const x of d[k]){if(typeof x.id!=='string'||!/^[-A-Za-z0-9_]+$/.test(x.id)||ids.has(x.id))throw Error('شناسه تکراری یا نامعتبر');ids.add(x.id)}const num=n=>typeof n==='number'&&Number.isSafeInteger(n);for(const p of d.products)if(!p.name||!p.code||![p.opening,p.price,p.cost].every(n=>num(n)&&n>=0))throw Error('کالای نامعتبر');if(new Set(d.products.map(p=>p.code)).size!==d.products.length)throw Error('رفرنس تکراری');for(const p of d.parties)if(!p.name||!num(p.opening)||!['customer','supplier'].includes(p.type))throw Error('طرف حساب نامعتبر');for(const i of d.invoices){if(!d.parties.some(p=>p.id===i.partyId)||!['sale','purchase'].includes(i.type)||!Array.isArray(i.items)||!i.items.length||!num(i.discount)||!num(i.paid)||i.discount<0||i.paid<0||!validDate(i.date))throw Error('فاکتور نامعتبر');for(const l of i.items)if(!d.products.some(p=>p.id===l.productId)||!num(l.qty)||l.qty<1||!num(l.price)||l.price<0)throw Error('ردیف فاکتور نامعتبر');if(total(i)<0||i.paid>total(i))throw Error('مبلغ فاکتور نامعتبر')}for(const k of ['payments','checks'])for(const x of d[k])if(!d.parties.some(p=>p.id===x.partyId)||!num(x.amount)||x.amount<=0||!validDate(x.date))throw Error('تراکنش نامعتبر');for(const c of d.checks)if(!['pending','returned','cleared'].includes(c.status))throw Error('وضعیت چک نامعتبر');return true}
function validDate(s){return typeof s==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(s)&&!isNaN(Date.parse(s))}
async function restoreFile(f){if(!f)return;try{const d=convertToIRR(JSON.parse(await f.text()));validateBackup(d);if(!confirm('اطلاعات فعلی با این پشتیبان جایگزین شود؟ ابتدا نسخه فعلی دانلود می‌شود.'))return;backup();const old=state;state=normalizeData(d);state.audit=[...new Map([...(old.audit||[]),...state.audit].map(a=>[a.id,a])).values()];state.audit.push({id:uid(),entity:'system',entityId:'restore',action:'update',at:new Date().toISOString(),user:currentActor(),changes:[{field:'note',before:null,after:'بازیابی پشتیبان با تأیید کاربر'}],snapshot:{name:'بازیابی پشتیبان'}});if(!save()){state=old;return}render();toast('پشتیبان بازیابی شد.')}catch(e){toast('بازیابی انجام نشد: '+e.message)}}
function clearDemo(){if(!confirm('همه اطلاعات فعلی پاک شود و از ابتدا شروع کنید؟'))return;backup();commit(()=>state=emptySeed())}
function old051ImportForm(){show('ورود گروهی کالا از اکسل',`<div class="formbody"><p>فایل XLSX یا CSV را انتخاب کن. ردیف اول باید نام ستون‌ها باشد. رفرنس تکراری وارد نمی‌شود و اطلاعات قبلی تغییر نمی‌کند.</p><div class="notice" style="margin-top:15px">ستون‌ها: کد، نام، برند، قیمت خرید، قیمت فروش، موجودی<br>قیمت‌ها به ریال و اعداد بدون جداکننده باشند. فقط اولین برگه فایل XLSX خوانده می‌شود.</div><div class="actions"><button class="btn" onclick="downloadTemplate()">دانلود قالب اکسل (CSV)</button><input aria-label="انتخاب فایل کالا" type="file" accept=".csv,.xlsx" onchange="previewImport(this.files[0])"></div><div id="importPreview" style="margin-top:20px"></div></div>`)}
function old051DownloadTemplate(){download('mavon-products-template.csv','\ufeffکد,نام,برند,قیمت خرید,قیمت فروش,موجودی\r\nBL-001,ساعت نمونه,BELMOND,40000000,60000000,10','text/csv;charset=utf-8')}
function csvParse(s){s=s.replace(/^\uFEFF/,'');let rows=[],row=[],val='',quoted=false;let sep=s.split(/\r?\n/)[0].includes(';')?';':',';for(let i=0;i<s.length;i++){let c=s[i];if(c==='"'){if(quoted&&s[i+1]==='"'){val+='"';i++}else quoted=!quoted}else if(c===sep&&!quoted){row.push(val);val=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&s[i+1]==='\n')i++;row.push(val);if(row.some(v=>v.trim()))rows.push(row);row=[];val=''}else val+=c}row.push(val);if(row.some(v=>v.trim()))rows.push(row);return rows}
async function readXLSX(file){let buf=await file.arrayBuffer(),v=new DataView(buf),end=-1;for(let i=v.byteLength-22;i>=Math.max(0,v.byteLength-65557);i--)if(v.getUint32(i,true)===0x06054b50){end=i;break}if(end<0)throw Error('فایل XLSX معتبر نیست');let pos=v.getUint32(end+16,true),count=v.getUint16(end+10,true),entries={};for(let i=0;i<count;i++){if(v.getUint32(pos,true)!==0x02014b50)throw Error('ساختار فایل پشتیبانی نمی‌شود');let method=v.getUint16(pos+10,true),size=v.getUint32(pos+20,true),unpacked=v.getUint32(pos+24,true),nl=v.getUint16(pos+28,true),el=v.getUint16(pos+30,true),cl=v.getUint16(pos+32,true),offset=v.getUint32(pos+42,true),name=new TextDecoder().decode(new Uint8Array(buf,pos+46,nl));if(unpacked>12000000)throw Error('فایل بیش از حد بزرگ است');entries[name]={method,size,offset};pos+=46+nl+el+cl}async function xml(name){let e=entries[name];if(!e)return null;let off=e.offset+30+v.getUint16(e.offset+26,true)+v.getUint16(e.offset+28,true),data=new Uint8Array(buf,off,e.size),s;if(e.method===0)s=new TextDecoder().decode(data);else if(e.method===8){try{s=await new Response(new Blob([data]).stream().pipeThrough(new DecompressionStream('deflate-raw'))).text()}catch{throw Error('این مرورگر فایل XLSX را باز نمی‌کند؛ از اکسل خروجی CSV بگیرید.')}}else throw Error('فشرده‌سازی پشتیبانی نمی‌شود');return new DOMParser().parseFromString(s,'application/xml')}
let strings=await xml('xl/sharedStrings.xml'),shared=strings?[...strings.getElementsByTagName('si')].map(n=>[...n.getElementsByTagName('t')].map(x=>x.textContent).join('')):[],wb=await xml('xl/workbook.xml'),rels=await xml('xl/_rels/workbook.xml.rels'),first=wb?.getElementsByTagName('sheet')[0],rid=first?.getAttribute('r:id'),target=[...(rels?.getElementsByTagName('Relationship')||[])].find(r=>r.getAttribute('Id')===rid)?.getAttribute('Target')||'worksheets/sheet1.xml';let path=target.startsWith('/')?target.slice(1):'xl/'+target;const sheet=await xml(path);if(!sheet)throw Error('برگه اکسل پیدا نشد');return [...sheet.getElementsByTagName('row')].map(r=>{let row=[];for(const c of r.getElementsByTagName('c')){let col=c.getAttribute('r').replace(/\d/g,''),idx=0;for(const ch of col)idx=idx*26+ch.charCodeAt(0)-64;let t=c.getAttribute('t'),val=c.getElementsByTagName('v')[0]?.textContent||'';row[idx-1]=t==='s'?shared[+val]:t==='inlineStr'?[...c.getElementsByTagName('t')].map(x=>x.textContent).join(''):val}return row})}
let importDraft=[];function numCell(x){return Number(String(x??'').replace(/[۰-۹]/g,c=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(c)).replace(/[٠-٩]/g,c=>'٠١٢٣٤٥٦٧٨٩'.indexOf(c)).replace(/[,٬\s]/g,''))}
async function old051PreviewImport(file){if(!file)return;try{if(file.size>5000000)throw Error('حداکثر حجم فایل ۵ مگابایت است.');const rows=file.name.toLowerCase().endsWith('.xlsx')?await readXLSX(file):csvParse(await file.text());const headers=(rows.shift()||[]).map(x=>String(x).trim());const keys=['کد','نام','برند','قیمت خرید','قیمت فروش','موجودی'];if(keys.some(k=>!headers.includes(k)))throw Error('نام ستون‌ها با قالب نمونه یکسان نیست.');const seen=new Set(state.products.map(p=>p.code));let invalid=0,duplicate=0;importDraft=[];for(const row of rows){if(!row.some(x=>String(x??'').trim()))continue;let r=Object.fromEntries(keys.map(k=>[k,row[headers.indexOf(k)]])),p={id:uid(),code:String(r['کد']??'').trim(),name:String(r['نام']??'').trim(),brand:String(r['برند']??'').trim(),cost:numCell(r['قیمت خرید']),price:numCell(r['قیمت فروش']),opening:numCell(r['موجودی'])};if(!p.code||!p.name||![p.cost,p.price,p.opening].every(n=>Number.isSafeInteger(n)&&n>=0&&n<=1e12)){invalid++;continue}if(seen.has(p.code)){duplicate++;continue}seen.add(p.code);importDraft.push(p)}$('#importPreview').innerHTML=`<div class="notice">${fmt(importDraft.length)} کالای آماده ورود · ${fmt(duplicate)} رفرنس تکراری · ${fmt(invalid)} ردیف نامعتبر</div>`+table(['رفرنس','نام','موجودی'],importDraft.slice(0,5).map(p=>`<tr><td>${esc(p.code)}</td><td>${esc(p.name)}</td><td>${fmt(p.opening)}</td></tr>`).join(''))+`<button class="btn primary" style="margin-top:18px" onclick="finishImport()" ${!importDraft.length?'disabled':''}>تأیید و ورود ${fmt(importDraft.length)} کالا</button>`}catch(e){importDraft=[];$('#importPreview').textContent=e.message}}
