function defaultGroups(){return [{id:'g-customer',name:'مشتریان عمومی',type:'customer'},{id:'g-supplier',name:'تأمین‌کنندگان عمومی',type:'supplier'}]}
function normalizeData(d){if(!Array.isArray(d.warehouses))d.warehouses=[{id:'wh-main',name:'انبار اصلی',address:''}];if(!Array.isArray(d.transfers))d.transfers=[];for(const p of d.products||[])if(!p.openingWarehouseId)p.openingWarehouseId='wh-main';for(const r of [...(d.invoices||[]),...(d.returns||[])])if(!r.warehouseId)r.warehouseId='wh-main';if(!Array.isArray(d.groups))d.groups=defaultGroups();if(!Array.isArray(d.staff))d.staff=[];if(!Array.isArray(d.returns))d.returns=[];if(!Array.isArray(d.audit))d.audit=[];for(const p of d.parties||[])if(!p.groupId)p.groupId=d.groups.find(g=>g.type===p.type)?.id||'';return d}
const modulePages={accounts:[['accounts','حساب مشتریان']],details:[['details','تعاریف پایه'],['groups','گروه‌های تفصیلی'],['parties','تعریف اشخاص']],finance:[['finance','امور مالی'],['payments','دریافت و پرداخت'],['checks','دفتر چک‌ها'],['reports','صورت حساب‌ها'],['cashflow','گزارش نقد و چک']],warehouse:[['warehouse','انبار'],['products','تعریف کالا'],['cardex','کاردکس کالا'],['inventory','گزارش موجودی'],['warehouses','تعریف انبار'],['transfers','انتقال کالا']],trade:[['trade','بازرگانی'],['invoices','خرید و فروش'],['returns','فاکتورهای مرجوعی'],['suppliers','حساب تأمین‌کنندگان'],['pricing','قیمت‌گذاری']]};
