function tiles(items){return `<div class="modulegrid">${items.filter(([id])=>can(id)).map(([id,name,desc,tag])=>`<button class="modulecard" onclick="go('${id}')"><div class="moduleicon">${tag||'↗'}</div><b>${name}</b><p>${desc}</p><span class="modulearrow">ورود به بخش ←</span></button>`).join('')}</div>`}
function dashboard(){if(DEMO_MODE)return splitDemo();return ``+title('خانه کسب‌وکار','معین، از اینجا وارد فضای کاری موردنظرت شو.')+`<div class="welcome"><div><span class="eyebrow">YOUR BUSINESS, ORGANIZED</span><h2>هر کار، در جای خودش.</h2><p>حساب‌ها، انبار و فروش؛ بخش‌های مستقل، اطلاعات مرتبط.</p></div><span class="welcome-logo">M</span></div>`+tiles([['accounts','حساب مشتریان','مانده حساب و گردش معاملات هر مشتری','۰۱'],['details','گروه‌های تفصیلی','گروه‌بندی و تعریف مشتری و تأمین‌کننده','۰۲'],['finance','امور مالی','دریافت، پرداخت، چک و صورت حساب','۰۳'],['warehouse','انبار','تعریف کالا، موجودی و کاردکس','۰۴'],['trade','بازرگانی و فروش','فاکتور خرید، فروش و مرجوعی','۰۵'],['access','دسترسی پرسنل','تعریف پرسنل و تنظیم الگوی دسترسی','۰۶']])+`<div class="helper" style="margin-top:22px">اطلاعات این دستگاه محلی ذخیره می‌شود؛ برای اشتراک اطلاعات بین دستگاه‌ها، همگام‌سازی را از بالای صفحه فعال کنید.</div>`}
function details(){return title('گروه‌های تفصیلی و تعاریف','ابتدا گروه را بساز، سپس اشخاص را در گروه مربوط تعریف کن.')+tiles([['groups','گروه‌های تفصیلی','ساخت گروه مشتریان و تأمین‌کنندگان','◫'],['parties','تعریف اشخاص','ثبت مشخصات و انتساب به گروه تفصیلی','＋']])}
function finance(){return title('امور مالی','دریافت‌ها، پرداخت‌ها و اسناد مالی در یک فضای مستقل.')+tiles([['payments','دریافت و پرداخت','ثبت گردش وجوه و پیگیری تسویه‌ها','↔'],['checks','دفتر چک‌ها','چک‌های دریافتی، پرداختی و سررسیدها','▤'],['reports','صورت حساب‌ها','ریز گردش حساب طرف‌های معامله','≡'],['cashflow','گزارش نقد و چک','همه دریافت‌ها و پرداخت‌ها در یک ستون مبلغ','↔']])}
function warehouse(){return title('انبار','موجودی و تاریخچه حرکت هر کالا، مستقل از بخش فروش.')+tiles([['products','تعریف کالا','تعریف تکی، ورود اکسل و اصلاح مشخصات کالا','＋'],['cardex','کاردکس کالا','ورود و خروج و اسناد انتقال','≡'],['inventory','گزارش موجودی','قیمت، ارزش موجودی و جمع کل','▤'],['warehouses','تعریف انبار','انبارهای مستقل و نشانی آن‌ها','＋'],['transfers','انتقال بین انبارها','جابه‌جایی چند کالا با یک سند','↔']])}
function trade(){return title('بازرگانی و فروش','تمام مراحل خرید و فروش و برگشت کالا.')+tiles([['invoices','فاکتورهای خرید و فروش','ثبت معامله و چاپ فاکتور','▤'],['returns','فاکتورهای مرجوعی','برگشت از فروش یا خرید با ارجاع به فاکتور اصلی','↩'],['suppliers','حساب تأمین‌کنندگان','مانده و گردش حساب تأمین‌کنندگان','◉'],['pricing','قیمت‌گذاری کالاها','اصلاح گروهی قیمت خرید و فروش','▤']])}
function accountList(kind){let list=state.parties.filter(p=>p.type===kind&&(p.name+p.phone).includes(query));return title(kind==='customer'?'حساب مشتریان':'حساب تأمین‌کنندگان','برای دیدن گردش کامل، ریز حساب را باز کن.',`<button class="btn" onclick="go('parties')">تعریف / ویرایش اشخاص</button>`)+`<div class="toolbar"><input placeholder="جست‌وجوی نام یا تلفن…" value="${esc(query)}" oninput="filterPage(this.value)"></div>`+panel('حساب‌ها',table(['نام','گروه تفصیلی','مانده حساب','وضعیت',''],list.map(p=>{let b=balance(p.id);return `<tr><td><b>${esc(p.name)}</b><div class="sub">${esc(p.phone)}</div></td><td>${esc(state.groups.find(g=>g.id===p.groupId)?.name||'بدون گروه')}</td><td>${money(Math.abs(b))}</td><td><span class="badge ${b===0?'ok':'warn'}">${b===0?'تسویه':b>0?(kind==='customer'?'بدهکار به ما':'طلبکار از ما'):(kind==='customer'?'طلبکار از ما':'بدهکار به ما')}</span></td><td><button class="btn small" onclick="ledger('${p.id}')">ریز حساب</button></td></tr>`}).join('')))}
function accounts(){return accountList('customer')}function suppliers(){return accountList('supplier')}
function parties(){return title('تعریف اشخاص','مشخصات پایه اشخاص و گروه تفصیلی؛ حساب‌ها در بخش مستقل خودشان هستند.',`<button class="btn primary" onclick="partyForm()">＋ تعریف شخص</button>`)+`<div class="toolbar"><input placeholder="جست‌وجوی نام یا تلفن…" value="${esc(query)}" oninput="filterPage(this.value)"></div>`+panel('اشخاص',table(['نام','نوع','گروه تفصیلی','تلفن',''],state.parties.filter(p=>(p.name+p.phone).includes(query)).map(p=>`<tr><td><b>${esc(p.name)}</b></td><td>${p.type==='customer'?'مشتری':'تأمین‌کننده'}</td><td>${esc(state.groups.find(g=>g.id===p.groupId)?.name||'بدون گروه')}</td><td>${esc(p.phone)}<div class="sub">${esc([p.province,p.city,p.address].filter(Boolean).join('، '))}</div></td><td><button class="btn small" onclick="partyForm('${p.id}')">ویرایش مشخصات</button></td></tr>`).join('')))}
function partyGroupOptions(type,selected){const e=$('[name="groupId"]');if(e)e.innerHTML=state.groups.filter(g=>g.type===type).map(g=>`<option value="${g.id}" ${g.id===selected?'selected':''}>${esc(g.name)}</option>`).join('')}
function groups(){return title('گروه‌های تفصیلی','گروه‌هایی مثل مشتریان عمده، مشتریان خرده و تأمین‌کنندگان داخلی.',`<button class="btn primary" onclick="groupForm()">＋ گروه جدید</button>`)+panel('فهرست گروه‌ها',table(['نام گروه','نوع اشخاص','تعداد اشخاص',''],state.groups.map(g=>`<tr><td><b>${esc(g.name)}</b></td><td>${g.type==='customer'?'مشتریان':'تأمین‌کنندگان'}</td><td>${fmt(state.parties.filter(p=>p.groupId===g.id).length)}</td><td><button class="btn small" onclick="groupForm('${g.id}')">ویرایش نام</button></td></tr>`).join('')))}
function groupForm(id){const g=state.groups.find(g=>g.id===id)||{};show(id?'ویرایش گروه':'گروه تفصیلی جدید',formWrap(`<div class="fields">${field('نام گروه','name',g.name,'text','required maxlength="100"')}<label>نوع اشخاص<select name="type" ${id?'disabled':''}><option value="customer">مشتری</option><option value="supplier" ${g.type==='supplier'?'selected':''}>تأمین‌کننده</option></select></label></div>`,`submitGroup(this,'${id||''}')`));if(id)$('#modalBody').insertAdjacentHTML('beforeend',recordMeta('groups',id))}
function submitGroup(form,id){const d=Object.fromEntries(new FormData(form)),name=d.name.trim(),type=id?state.groups.find(g=>g.id===id).type:d.type;if(!name)return toast('نام گروه را بنویسید.');if(state.groups.some(g=>g.id!==id&&g.type===type&&g.name===name))return toast('این گروه قبلاً تعریف شده است.');if(commit(()=>{if(id)state.groups.find(g=>g.id===id).name=name;else state.groups.push({id:uid(),name,type})})){$('#modal').close();toast('گروه ذخیره شد.')}}
function returnTotal(r){return r.items.reduce((s,l)=>s+l.amount,0)}
function old050StockMovements(id){let rows=[];for(const i of state.invoices){for(const l of i.items.filter(l=>l.productId===id))rows.push({date:i.date,createdAt:i.createdAt||'',number:i.number,partyId:i.partyId,label:i.type==='sale'?'فروش':'خرید',delta:l.qty*(i.type==='sale'?-1:1),documentId:i.id,kind:'invoice'})}for(const r of state.returns){for(const l of r.items.filter(l=>l.productId===id))rows.push({date:r.date,createdAt:r.createdAt,number:r.number,partyId:r.partyId,label:r.type==='sale'?'برگشت از فروش':'برگشت از خرید',delta:l.qty*(r.type==='sale'?1:-1),documentId:r.id,kind:'return'})}return rows.sort((a,b)=>a.date.localeCompare(b.date)||(a.createdAt||'').localeCompare(b.createdAt||''))}
let cardexProduct='';
function previousCardex(){if(!state.products.some(p=>p.id===cardexProduct))cardexProduct=state.products[0]?.id||'';return title('کاردکس کالا','تاریخچه ورود و خروج، با شماره سند و مانده تعدادی.')+`<div class="toolbar"><label>انتخاب کالا <select onchange="cardexProduct=this.value;render()">${state.products.map(p=>`<option value="${p.id}" ${p.id===cardexProduct?'selected':''}>${esc(p.name)} — ${esc(p.code)}</option>`).join('')}</select></label></div>`+(cardexProduct?cardexHTML(cardexProduct):'<div class="empty">ابتدا کالا تعریف کن.</div>')}
function showCardex(id){cardexSearch='';cardexProduct=id;go('cardex')}
function previousCardexHTML(id){const p=state.products.find(p=>p.id===id);let b=p.opening,rows=`<tr><td>—</td><td>مانده اول دوره</td><td>—</td><td>—</td><td>${fmt(p.opening)}</td><td>—</td><td>${fmt(b)}</td></tr>`;for(const m of stockMovements(id)){b+=m.delta;rows+=`<tr><td>${pdate(m.date)}</td><td>${m.label}</td><td><button class="link" onclick="${m.kind==='return'?'viewReturn':'viewInvoice'}('${m.documentId}')">${esc(m.number)}</button></td><td>${esc(state.parties.find(x=>x.id===m.partyId)?.name)}</td><td>${m.delta>0?fmt(m.delta):'—'}</td><td>${m.delta<0?fmt(-m.delta):'—'}</td><td>${fmt(b)}</td></tr>`}return panel(esc(p.name),table(['تاریخ','نوع گردش','شماره سند','طرف حساب','ورود','خروج','مانده'],rows),`<span class="badge ok">موجودی فعلی: ${fmt(stock(id))} عدد</span>`)}
function returnedQty(invoiceId,index){return state.returns.filter(r=>r.invoiceId===invoiceId).flatMap(r=>r.items).filter(l=>l.sourceIndex===index).reduce((s,l)=>s+l.qty,0)}
// Allocate the original net total across rows, then across partial returns.
// Cumulative integer allocation makes a full return exactly equal the original total.
function netRow(i,index){if(i.items[index].returnNetAmount!==undefined)return i.items[index].returnNetAmount;const gross=i.items.reduce((s,l)=>s+l.qty*l.price,0);if(!gross)return 0;const before=i.items.slice(0,index).reduce((s,l)=>s+l.qty*l.price,0),after=before+i.items[index].qty*i.items[index].price;return Number(BigInt(after)*BigInt(total(i))/BigInt(gross)-BigInt(before)*BigInt(total(i))/BigInt(gross))}
function refundAmount(i,index,qty,prior=returnedQty(i.id,index)){const row=netRow(i,index),q=i.items[index].qty;const scale=BigInt(i.items[index].returnAllocationScale||1);return Number((BigInt(row)/scale*BigInt(prior+qty)/BigInt(q)-BigInt(row)/scale*BigInt(prior)/BigInt(q))*scale)}
function returns(){return title('فاکتورهای مرجوعی','مرجوعی مرتبط با فاکتور اصلی؛ با اصلاح موجودی و حساب.',`<button class="btn primary" onclick="returnForm()">＋ فاکتور مرجوعی</button>`)+panel('برگشت از خرید و فروش',table(['شماره مرجوعی','فاکتور اصلی','طرف حساب','تاریخ','نوع','مبلغ',''],[...state.returns].reverse().map(r=>`<tr><td>${esc(r.number)}</td><td>${esc(state.invoices.find(i=>i.id===r.invoiceId)?.number)}</td><td>${esc(state.parties.find(p=>p.id===r.partyId)?.name)}</td><td>${pdate(r.date)}</td><td><span class="badge warn">${r.type==='sale'?'برگشت از فروش':'برگشت از خرید'}</span></td><td>${money(returnTotal(r))}</td><td><button class="btn small" onclick="viewReturn('${r.id}')">مشاهده و چاپ</button></td></tr>`).join('')))}
function old050ReturnForm(invoiceId){if(!state.invoices.length)return toast('اول فاکتور خرید یا فروش ثبت کن.');const i=state.invoices.find(i=>i.id===invoiceId)||state.invoices[0];show('ثبت فاکتور مرجوعی',formWrap(`<div class="fields"><label class="wide">فاکتور اصلی<select name="invoiceId" onchange="returnForm(this.value)">${state.invoices.map(x=>`<option value="${x.id}" ${i.id===x.id?'selected':''}>${esc(x.number)} · ${x.type==='sale'?'فروش':'خرید'} · ${esc(state.parties.find(p=>p.id===x.partyId)?.name)}</option>`).join('')}</select></label>${field('تاریخ مرجوعی','date',day(),'date','required')}${field(i.type==='sale'?'وجه بازپرداخت‌شده به مشتری (ریال)':'وجه پس‌گرفته از تأمین‌کننده (ریال)','paid',0,'number','required min="0" step="1"')}</div><div class="notice" style="margin-top:20px">تعداد مرجوعی هر ردیف را وارد کن. مبلغ با کسر سهم تخفیف فاکتور اصلی محاسبه می‌شود. مبلغی که نقداً تسویه نشده، مانده حساب را کاهش می‌دهد.</div><div id="returnLines">${i.items.map((l,n)=>`<label class="returnline"><span><b>${esc(l.name)}</b><small>فاکتور: ${fmt(l.qty)} · قبلاً مرجوع: ${fmt(returnedQty(i.id,n))} · باقیمانده: ${fmt(l.qty-returnedQty(i.id,n))}</small></span><input aria-label="تعداد مرجوعی ردیف ${n+1}" data-index="${n}" type="text" data-numeric inputmode="numeric" min="0" max="${l.qty-returnedQty(i.id,n)}" step="1" value="0" required oninput="calcReturn()"></label>`).join('')}</div><label style="display:block;margin-top:18px">علت مرجوعی<textarea style="display:block;width:100%;margin-top:8px" name="reason" maxlength="500" required></textarea></label><div class="previewtotal" id="returnTotal">مبلغ مرجوعی: ۰ ریال</div>`,`submitReturn(this)`))}
function old050ReturnInputs(){return [...document.querySelectorAll('#returnLines input')].map(x=>({index:+x.dataset.index,qty:numCell(x.value)})).filter(x=>x.qty!==0)}
function old050CalcReturn(){const i=state.invoices.find(i=>i.id===$('[name="invoiceId"]').value);const inputs=returnInputs();if(inputs.some(x=>!Number.isSafeInteger(x.qty)||x.qty<0||x.qty>i.items[x.index].qty-returnedQty(i.id,x.index))){$('#returnTotal').textContent='تعداد مرجوعی معتبر وارد کنید.';return}$('#returnTotal').textContent='مبلغ مرجوعی: '+money(inputs.reduce((s,x)=>s+refundAmount(i,x.index,x.qty),0))}
function buildReturn(invoiceId,inputs,paid,date,reason){const i=state.invoices.find(i=>i.id===invoiceId);if(!i||!inputs.length)throw Error('حداقل یک ردیف را برای مرجوعی انتخاب کن.');if(!validDate(date)||date<i.date)throw Error('تاریخ مرجوعی نمی‌تواند قبل از فاکتور اصلی باشد.');const seen=new Set();const items=inputs.map(x=>{const l=i.items[x.index];if(!l||seen.has(x.index)||!Number.isSafeInteger(x.qty)||x.qty<1||x.qty>l.qty-returnedQty(i.id,x.index))throw Error('تعداد مرجوعی از مقدار قابل برگشت بیشتر است.');seen.add(x.index);return {sourceIndex:x.index,productId:l.productId,name:l.name,code:l.code,qty:x.qty,amount:refundAmount(i,x.index,x.qty)}});if(i.type==='purchase')for(const id of new Set(items.map(l=>l.productId)))if(items.filter(l=>l.productId===id).reduce((s,l)=>s+l.qty,0)>stock(id))throw Error('موجودی برای برگشت از خرید کافی نیست.');const amount=items.reduce((s,l)=>s+l.amount,0);if(!Number.isSafeInteger(paid)||paid<0||paid>amount)throw Error('وجه تسویه از مبلغ مرجوعی بیشتر است.');return {id:uid(),number:documentNumber('R-',state.returns.length+1001),invoiceId:i.id,type:i.type,partyId:i.partyId,date,paid,reason:reason.trim(),items,createdAt:new Date().toISOString()}}
function old050SubmitReturn(form){const d=Object.fromEntries(new FormData(form));try{const r=buildReturn(d.invoiceId,returnInputs(),+d.paid,d.date,d.reason);if(commit(()=>state.returns.push(r))){toast('مرجوعی ثبت شد؛ موجودی و حساب اصلاح شد.');viewReturn(r.id)}}catch(e){toast(e.message)}}
function returnHTML(r){const i=state.invoices.find(i=>i.id===r.invoiceId);return `<h1>ماوون | ${r.type==='sale'?'برگشت از فروش':'برگشت از خرید'}</h1><p style="margin:20px 0">شماره ${esc(r.number)} · تاریخ ${pdate(r.date)}<br>انبار: ${esc(warehouseName(r.warehouseId))}<br>فاکتور اصلی: ${esc(i.number)} · طرف حساب: ${esc(state.parties.find(p=>p.id===r.partyId)?.name)}</p>`+table(['رفرنس','کالا','تعداد مرجوعی','مبلغ خالص (ریال)'],r.items.map(l=>`<tr><td>${esc(l.code)}</td><td>${esc(l.name)}</td><td>${fmt(l.qty)}</td><td>${fmt(l.amount)}</td></tr>`).join(''))+`<div class="previewtotal">مبلغ مرجوعی: ${money(returnTotal(r))}</div><p>تسویه نقدی مرجوعی: ${money(r.paid)}<br>کاهش مانده حساب: ${money(returnTotal(r)-r.paid)}<br>علت: ${esc(r.reason)}</p>`}
function viewReturn(id){if(!can('trade'))return toast('اجازه مشاهده مرجوعی ندارید.');const r=state.returns.find(r=>r.id===id);show('فاکتور مرجوعی',`<div class="formbody">${returnHTML(r)}${recordMeta('returns',r.id)}${editAction('returns',r.id)}<button class="btn primary" style="margin-top:22px" onclick="printReturn('${id}')">چاپ / ذخیره PDF</button></div>`)}
function printReturn(id){$('#printarea').innerHTML=returnHTML(state.returns.find(r=>r.id===id));window.print()}
function previousLedger(id){const p=state.parties.find(p=>p.id===id);const rows=[{date:'0000',label:'مانده اول دوره',debit:p.opening,credit:0}];state.invoices.filter(i=>i.partyId===id).forEach(i=>rows.push({date:i.date,label:'فاکتور '+i.number,debit:total(i),credit:i.paid}));state.payments.filter(x=>x.partyId===id).forEach(x=>rows.push({date:x.date,label:x.note||'تراکنش',debit:0,credit:x.amount}));state.returns.filter(r=>r.partyId===id).forEach(r=>rows.push({date:r.date,label:(r.type==='sale'?'برگشت از فروش ':'برگشت از خرید ')+r.number,debit:r.paid,credit:returnTotal(r)}));rows.sort((a,b)=>a.date.localeCompare(b.date));let b=0;const html=`<h2>ریز حساب ${esc(p.name)}</h2><p style="margin:12px 0">${p.type==='customer'?'مانده مثبت: بدهی مشتری به شما':'مانده مثبت: طلب تأمین‌کننده از شما'} · مبالغ به ریال</p>`+table(['تاریخ','شرح','افزایش مانده','کاهش مانده','مانده'],rows.map(r=>{b+=r.debit-r.credit;return `<tr><td>${r.date==='0000'?'—':pdate(r.date)}</td><td>${esc(r.label)}</td><td>${fmt(r.debit)}</td><td>${fmt(r.credit)}</td><td>${fmt(b)}</td></tr>`}).join(''))+`<div class="previewtotal">مانده نهایی: ${money(b)}</div>`;show('صورت حساب',`<div class="formbody">${html}<button class="btn primary" style="margin-top:22px" id="printLedger">چاپ ریز حساب</button></div>`);$('#printLedger').onclick=()=>{$('#printarea').innerHTML=html;window.print()}}
const accessModules=[['accounts','حساب مشتریان'],['details','تعاریف و گروه‌ها'],['finance','امور مالی'],['warehouse','انبار'],['trade','بازرگانی و فروش']];
function access(){if(typeof window!=='undefined'&&window.MavonAuth)return title('مدیریت کاربران','نام کاربری، رمز مستقل و دسترسی واقعی پرسنل روی سرور.',`<button class="btn primary" onclick="MavonSync.members()">تعریف و مدیریت کاربران</button>`);return title('مدیریت دسترسی پرسنل','تعریف پرسنل و نگهداری الگوی دسترسی هر بخش.',`<button class="btn primary" onclick="staffForm()">＋ تعریف پرسنل</button>`)+`<div class="notice"><b>وضعیت: فقط تنظیمات آزمایشی.</b> اجازه مشاهده، ثبت و اصلاح در رابط آزمایشی اعمال می‌شود. با «کاربر آزمایشی» بالای صفحه می‌توانی نقش را امتحان کنی. ورود امن و محدودیت سمت سرور هنوز فعال نیست و حساب ورود ساخته نمی‌شود.</div>`+panel('پرسنل و الگوهای دسترسی',table(['نام','سمت','وضعیت الگو','بخش‌های مجاز',''],state.staff.map(s=>`<tr><td><b>${esc(s.name)}</b><div class="sub">${esc(s.phone)}</div></td><td>${esc(s.role)}</td><td><span class="badge ${s.active?'ok':'warn'}">${s.active?'فعال':'غیرفعال'}</span></td><td>${esc(accessModules.filter(([id])=>s.permissions[id]?.view).map(x=>x[1]).join('، ')||'بدون دسترسی')}</td><td><button class="btn small" onclick="staffForm('${s.id}')">تنظیم دسترسی</button></td></tr>`).join('')))}
function staffForm(id){const s=state.staff.find(s=>s.id===id)||{active:true,permissions:{}};show(id?'ویرایش دسترسی پرسنل':'تعریف پرسنل',formWrap(`<div class="fields">${field('نام و نام خانوادگی','name',s.name,'text','required maxlength="100"')}${field('سمت','role',s.role,'text','required maxlength="100"')}${field('شماره تماس','phone',s.phone,'tel','maxlength="25"')}<label>وضعیت الگو<select name="active"><option value="yes">فعال</option><option value="no" ${!s.active?'selected':''}>غیرفعال</option></select></label></div><div class="notice" style="margin-top:20px">اجازه‌ها در حالت آزمایشی بررسی می‌شوند؛ کنترل امنیتی سمت سرور هنوز متصل نیست. اجازه ثبت یا ویرایش، مشاهده را هم فعال می‌کند.</div>${table(['بخش','مشاهده','ثبت','ویرایش'],accessModules.map(([key,label])=>`<tr><td>${label}</td>${['view','create','edit'].map(a=>`<td><input type="checkbox" name="${key}_${a}" aria-label="${label} ${a==='view'?'مشاهده':a==='create'?'ثبت':'ویرایش'}" ${s.permissions[key]?.[a]?'checked':''}></td>`).join('')}</tr>`).join(''))}`,`submitStaff(this,'${id||''}')`));if(id)$('#modalBody').insertAdjacentHTML('beforeend',recordMeta('staff',id))}
function submitStaff(form,id){const d=Object.fromEntries(new FormData(form)),permissions={};for(const [key] of accessModules){const create=!!d[key+'_create'],edit=!!d[key+'_edit'];permissions[key]={view:!!d[key+'_view']||create||edit,create,edit}}const s={id:id||uid(),name:d.name.trim(),role:d.role.trim(),phone:d.phone.trim(),active:d.active==='yes',permissions};if(!s.name||!s.role)return toast('نام و سمت را وارد کن.');if(commit(()=>{if(id)Object.assign(state.staff.find(x=>x.id===id),s);else state.staff.push(s)})){$('#modal').close();toast('سطح دسترسی آزمایشی ذخیره شد؛ می‌توانی با انتخاب کاربر آزمایش کنی.')}}
function before050ValidateBackup(d){for(const k of ['groups','staff','returns','audit'])if(d[k]!==undefined&&!Array.isArray(d[k]))throw Error('ساختار بخش‌های جدید معتبر نیست');if(d.audit!==undefined){const seen=new Set();for(const a of d.audit){if(!a||typeof a.id!=='string'||seen.has(a.id)||!a.entityId||!['create','update','delete'].includes(a.action)||!a.at||isNaN(Date.parse(a.at))||!a.user?.name||!Array.isArray(a.changes)||!a.snapshot)throw Error('تاریخچه پشتیبان معتبر نیست');seen.add(a.id)}}legacyValidateBackup(d);if(d.currency&&d.currency!=='IRR'&&d.currency!=='IRT')throw Error('واحد پول نامعتبر');const ext=normalizeData(JSON.parse(JSON.stringify(d)));if(![ext.groups,ext.staff,ext.returns].every(Array.isArray))throw Error('ساختار بخش‌های جدید معتبر نیست');const ids=new Set();for(const k of ['products','parties','invoices','payments','checks','groups','staff','returns'])for(const x of ext[k]){if(typeof x.id!=='string'||!/^[-A-Za-z0-9_]+$/.test(x.id)||ids.has(x.id))throw Error('شناسه تکراری یا نامعتبر');ids.add(x.id)}for(const g of ext.groups)if(!g.name||!['customer','supplier'].includes(g.type))throw Error('گروه تفصیلی نامعتبر');for(const p of ext.parties)if(!ext.groups.some(g=>g.id===p.groupId&&g.type===p.type))throw Error('گروه شخص پیدا نشد');const used=new Map();for(const r of ext.returns){const i=ext.invoices.find(i=>i.id===r.invoiceId);if(!i||r.partyId!==i.partyId||r.type!==i.type||!validDate(r.date)||r.date<i.date||!Array.isArray(r.items)||!r.items.length||!Number.isSafeInteger(r.paid)||r.paid<0)throw Error('مرجوعی نامعتبر');const seen=new Set();for(const l of r.items){const src=i.items[l.sourceIndex],key=i.id+':'+l.sourceIndex,prior=used.get(key)||0;if(!src||seen.has(l.sourceIndex)||l.productId!==src.productId||!Number.isSafeInteger(l.qty)||l.qty<1||prior+l.qty>src.qty||!Number.isSafeInteger(l.amount)||l.amount!==refundAmount(i,l.sourceIndex,l.qty,prior))throw Error('تعداد یا مبلغ مرجوعی نامعتبر');used.set(key,prior+l.qty);seen.add(l.sourceIndex)}if(r.paid>returnTotal(r))throw Error('تسویه مرجوعی نامعتبر')}for(const s of ext.staff)if(!s.name||!s.role||typeof s.active!=='boolean'||!s.permissions||accessModules.some(([k])=>!s.permissions[k]||['view','create','edit'].some(a=>typeof s.permissions[k][a]!=='boolean')))throw Error('الگوی دسترسی نامعتبر');return true}

const entityNames={products:'کالا',parties:'شخص',groups:'گروه تفصیلی',invoices:'فاکتور',payments:'دریافت / پرداخت',checks:'چک',returns:'مرجوعی',staff:'پرسنل',warehouses:'انبار',transfers:'انتقال انبار'};
const fieldNames={name:'نام',code:'رفرنس',brand:'برند',price:'قیمت فروش',cost:'قیمت خرید',opening:'مانده اولیه',phone:'تلفن',groupId:'گروه تفصیلی',province:'استان',city:'شهر',address:'نشانی',warehouseId:'انبار سند',openingWarehouseId:'انبار موجودی اولیه',fromId:'انبار مبدأ',toId:'انبار مقصد',status:'وضعیت',currency:'واحد پول',receiptId:'شناسه دریافت ترکیبی',invoiceId:'فاکتور مرتبط',permissions:'دسترسی‌ها',active:'فعال بودن',role:'سمت',amount:'مبلغ',date:'تاریخ',note:'شرح',method:'روش پرداخت',items:'ردیف‌ها',paid:'تسویه نقدی',discount:'تخفیف',reason:'علت مرجوعی',type:'نوع',partyId:'طرف حساب',number:'شماره',bank:'بانک'};
const checkStatuses={pending:'در انتظار',returned:'برگشتی',cleared:'وصول شده'};
function currentActor(){if(typeof window!=='undefined'&&window.MavonAuth?.user)return window.MavonAuth.user;if(typeof window!=='undefined'&&window.MavonSync?.actor())return window.MavonSync.actor();const selected=localStorage.getItem('mavon-active-staff');if(selected){const staff=state.staff.find(s=>s.id===selected);return {id:selected,name:staff?.name||'کاربر غیرفعال',verified:false}}return {id:'local-operator',name:localStorage.getItem('mavon-operator-name')||'معین احمدخان',verified:false}}
function stampTime(t){return t&&!isNaN(Date.parse(t))?new Date(t).toLocaleString('fa-IR',{timeZone:'Asia/Tehran',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}):'نامشخص (سابقه قدیمی)'}
function actorName(a){return a?.name||'نامشخص (سابقه قدیمی)'}
function appendAudit(before){const at=new Date().toISOString(),user=currentActor();state.audit=before.audit?JSON.parse(JSON.stringify(before.audit)):[];for(const entity of Object.keys(entityNames)){const old=new Map((before[entity]||[]).map(r=>[r.id,r])),now=new Map((state[entity]||[]).map(r=>[r.id,r]));for(const [id,r] of now){const prev=old.get(id),keys=new Set([...Object.keys(r),...Object.keys(prev||{})]);const changes=[...keys].filter(k=>!['createdAt','createdBy','updatedAt','updatedBy'].includes(k)&&JSON.stringify(prev?.[k])!==JSON.stringify(r[k])).map(field=>({field,before:prev?.[field]??null,after:r[field]??null}));if(prev&&!changes.length)continue;if(!prev){r.createdAt=at;r.createdBy={...user}}else {r.createdAt=prev.createdAt||null;r.createdBy=prev.createdBy||null}r.updatedAt=at;r.updatedBy={...user};state.audit.push({id:uid(),entity,entityId:id,action:prev?'update':'create',at,user:{...user},changes,snapshot:JSON.parse(JSON.stringify(r))})}for(const [id,r] of old)if(!now.has(id))state.audit.push({id:uid(),entity,entityId:id,action:'delete',at,user:{...user},changes:[],snapshot:JSON.parse(JSON.stringify(r))})}}
function commit(fn){if(typeof window!=='undefined'&&window.MavonAuth&&!window.MavonAuth.unlocked){toast('ابتدا وارد شوید.');return false}if(typeof window!=='undefined'&&window.MavonSync?.busy){toast('در حال همگام‌سازی هستیم؛ چند لحظه بعد ثبت کنید.');return false}const before=JSON.parse(JSON.stringify(state));try{fn();verifyMutationPermissions(before);appendAudit(before);if(!save()){state=before;return false}}catch(e){state=before;toast('ثبت انجام نشد: '+e.message);return false}render();return true}
function recordMeta(entity,id){const r=state[entity]?.find(r=>r.id===id);if(!r)return '';return `<div class="recordmeta"><div><b>ایجاد:</b> ${esc(stampTime(r.createdAt))} · ${esc(actorName(r.createdBy))}</div><div><b>آخرین تغییر:</b> ${esc(stampTime(r.updatedAt))} · ${esc(actorName(r.updatedBy))}</div><button class="link" type="button" onclick="recordHistory('${entity}','${id}')">مشاهده تاریخچه تغییرات ←</button></div>`}
function auditValue(v,field){if(['date','receivedDate'].includes(field)&&validDate(v))return pdate(v);if(v===null||v===undefined)return '—';if(field==='status')return checkStatuses[v]||String(v);if(['warehouseId','openingWarehouseId','fromId','toId'].includes(field))return warehouseName(v);if(field==='groupId')return state.groups.find(g=>g.id===v)?.name||v;if(field==='partyId')return state.parties.find(p=>p.id===v)?.name||v;if(typeof v==='object')return JSON.stringify(v);if(typeof v==='boolean')return v?'بله':'خیر';if(typeof v==='number')return fmt(v);return String(v)}
function auditTable(events){return table(['تاریخ و ساعت (تهران)','انجام‌دهنده','عملیات','مورد','تغییرات'],events.map(a=>`<tr><td>${esc(stampTime(a.at))}</td><td>${esc(actorName(a.user))}<div class="sub">نام محلی؛ تأییدنشده</div></td><td><span class="badge ${a.action==='create'?'ok':'warn'}">${a.action==='create'?'ایجاد':a.action==='delete'?'حذف':'ویرایش'}</span></td><td>${entityNames[a.entity]||'عملیات'}: ${esc(a.snapshot?.name||a.snapshot?.number||a.snapshot?.note||a.entityId)}</td><td class="auditdiff">${a.action==='create'?a.changes.filter(c=>fieldNames[c.field]).map(c=>`<div><b>${esc(fieldNames[c.field])}:</b> ${esc(auditValue(c.after,c.field))}</div>`).join('')||'ثبت اطلاعات اولیه':a.action==='delete'?'حذف رکورد':a.changes.map(c=>`<div><b>${esc(fieldNames[c.field]||c.field)}:</b> ${esc(auditValue(c.before,c.field))} ← ${esc(auditValue(c.after,c.field))}</div>`).join('')}</td></tr>`).join(''))}
function recordHistory(entity,id){if(!can(entityModule(entity)))return toast('اجازه مشاهده این تاریخچه را ندارید.');const r=state[entity]?.find(r=>r.id===id);show('تاریخچه '+(entityNames[entity]||''),`<div class="formbody"><p>${esc(r?.name||r?.number||'')}</p>${recordMeta(entity,id)}${auditTable(state.audit.filter(a=>a.entity===entity&&a.entityId===id).reverse())}<p class="helper" style="margin-top:16px">تاریخچه از نسخه ۰.۳ ثبت می‌شود؛ رویدادهای قبل از آن بازسازی نشده‌اند.</p></div>`)}
let historyQuery='';
function history(){const q=historyQuery.trim().toLowerCase(),events=[...state.audit].reverse().filter(a=>(JSON.stringify(a)+entityNames[a.entity]+(a.user?.name||'')).toLowerCase().includes(q));return title('تاریخچه عملیات','ایجاد و تغییر در همه بخش‌ها، همراه کاربر و زمان دقیق.')+`<div class="notice">این تاریخچه محلی است و هویت کاربر هنوز با ورود امن تأیید نمی‌شود. زمان ثبت با ساعت دستگاه گرفته و به وقت تهران نمایش داده می‌شود.</div><div class="toolbar"><input aria-label="جست‌وجوی تاریخچه" placeholder="نام کاربر، نام کالا یا شماره سند…" value="${esc(historyQuery)}" oninput="historyQuery=this.value;filterHistory()"><span class="helper">${fmt(events.length)} رویداد</span><button class="btn" onclick="operatorForm()">کاربر محلی: ${esc(currentActor().name)}</button></div>`+panel('دفتر رویدادها',auditTable(events))}
function filterHistory(){const pos=document.activeElement.selectionStart;render();const e=$('[aria-label="جست‌وجوی تاریخچه"]');e.focus();e.setSelectionRange(pos,pos)}
function operatorForm(){show('نام انجام‌دهنده محلی',`<form class="formbody" onsubmit="event.preventDefault();setOperator(this)"><div class="notice">این نام برای ثبت عملیات همین دستگاه است؛ ورود امن و احراز هویت پرسنل هنوز فعال نیست. تغییر نام، سوابق قبلی را تغییر نمی‌دهد.</div>${field('نام نمایشی انجام‌دهنده','operator',currentActor().name,'text','required maxlength="100"')}<div class="formfoot"><button class="btn primary">ذخیره نام محلی</button></div></form>`)}
function setOperator(form){const name=new FormData(form).get('operator').trim();if(!name)return;const previous=currentActor();try{localStorage.setItem('mavon-operator-name',name)}catch{return toast('نام ذخیره نشد.')}const snapshot=JSON.stringify(state);state.audit.push({id:uid(),entity:'system',entityId:'operator',action:'update',at:new Date().toISOString(),user:previous,changes:[{field:'name',before:previous.name,after:name}],snapshot:{name:'تغییر نام کاربر محلی'}});if(!save()){state=JSON.parse(snapshot);localStorage.setItem('mavon-operator-name',previous.name);return}$('#modal').close();render();toast('نام برای ثبت‌های بعدی تنظیم شد.')}
let cardexSearch='';
function old050Cardex(){const q=cardexSearch.trim().toLowerCase(),matches=state.products.filter(p=>(p.name+' '+p.code+' '+p.brand).toLowerCase().includes(q));if(!state.products.some(p=>p.id===cardexProduct))cardexProduct=state.products[0]?.id||'';return title('کاردکس کالا','نام، رفرنس یا برند را تایپ کن و کالا را از نتیجه جست‌وجو انتخاب کن.')+`<div class="toolbar"><input id="cardexSearch" aria-label="جست‌وجوی دستی کاردکس" placeholder="جست‌وجوی نام، رفرنس یا برند کالا…" value="${esc(cardexSearch)}" oninput="searchCardex(this.value)"><label>انتخاب کالا <select aria-label="انتخاب کالا" onchange="cardexProduct=this.value;render()">${matches.map(p=>`<option value="${p.id}" ${p.id===cardexProduct?'selected':''}>${esc(p.name)} — ${esc(p.code)}</option>`).join('')}</select></label></div><div class="cardex-results">${matches.map(p=>`<button class="btn small ${p.id===cardexProduct?'gold':''}" onclick="cardexProduct='${p.id}';render()">${esc(p.code)} · ${esc(p.name)}</button>`).join('')||'<div class="empty">کالایی با این عبارت پیدا نشد.</div>'}</div>`+(matches.some(p=>p.id===cardexProduct)?cardexHTML(cardexProduct):'')}
function searchCardex(v){cardexSearch=v;const q=v.trim().toLowerCase(),list=state.products.filter(p=>(p.name+' '+p.code+' '+p.brand).toLowerCase().includes(q));if(!list.some(p=>p.id===cardexProduct))cardexProduct=list[0]?.id||'';const pos=document.activeElement.selectionStart;render();$('#cardexSearch').focus();$('#cardexSearch').setSelectionRange(pos,pos)}
function old050CardexHTML(id){const p=state.products.find(p=>p.id===id);let b=p.opening,rows=`<tr><td>—</td><td>مانده اول دوره</td><td>—</td><td>—</td><td>${fmt(p.opening)}</td><td>—</td><td>${fmt(b)}</td><td>${esc(stampTime(p.createdAt))}</td><td>${esc(actorName(p.createdBy))}</td></tr>`;for(const m of stockMovements(id)){const doc=state[m.kind==='return'?'returns':'invoices'].find(r=>r.id===m.documentId);b+=m.delta;rows+=`<tr><td>${pdate(m.date)}</td><td>${m.label}</td><td><button class="link" onclick="${m.kind==='return'?'viewReturn':'viewInvoice'}('${m.documentId}')">${esc(m.number)}</button></td><td>${esc(state.parties.find(x=>x.id===m.partyId)?.name)}</td><td>${m.delta>0?fmt(m.delta):'—'}</td><td>${m.delta<0?fmt(-m.delta):'—'}</td><td>${fmt(b)}</td><td>${esc(stampTime(doc?.createdAt))}</td><td>${esc(actorName(doc?.createdBy))}</td></tr>`}return panel(esc(p.name),recordMeta('products',id)+table(['تاریخ سند','نوع گردش','شماره سند','طرف حساب','ورود','خروج','مانده','زمان ثبت (تهران)','ثبت‌کننده'],rows),`<span class="badge ok">موجودی فعلی: ${fmt(stock(id))} عدد</span>`)}
function old041LedgerEvents(id){const p=state.parties.find(p=>p.id===id),rows=[{date:'0000',phase:0,label:'مانده اول دوره',debit:p.opening,credit:0,at:p.createdAt,user:p.createdBy}];for(const i of state.invoices.filter(i=>i.partyId===id)){rows.push({date:i.date,phase:0,label:(i.type==='sale'?'فاکتور فروش ':'فاکتور خرید ')+i.number,debit:total(i),credit:0,at:i.createdAt,user:i.createdBy});if(i.paid)rows.push({date:i.date,phase:1,label:'تسویه نقدی هم‌زمان فاکتور '+i.number,debit:0,credit:i.paid,at:i.createdAt,user:i.createdBy})}for(const r of state.returns.filter(r=>r.partyId===id)){rows.push({date:r.date,phase:0,label:(r.type==='sale'?'برگشت از فروش ':'برگشت از خرید ')+r.number,debit:0,credit:returnTotal(r),at:r.createdAt,user:r.createdBy});if(r.paid)rows.push({date:r.date,phase:1,label:'تسویه نقدی مرجوعی '+r.number,debit:r.paid,credit:0,at:r.createdAt,user:r.createdBy})}for(const c of state.checks.filter(c=>c.partyId===id)){const events=state.audit.filter(a=>a.entity==='checks'&&a.entityId===c.id),creation=events.find(a=>a.action==='create');rows.push({date:c.receivedDate||(c.createdAt||'').slice(0,10)||'0001',phase:0,label:'ثبت چک '+c.number+' · '+c.bank+' · مبلغ '+money(c.amount)+' · سررسید '+pdate(c.date),debit:0,credit:0,at:c.createdAt,user:c.createdBy,informational:true});if(!creation)rows.push({date:(c.updatedAt||'').slice(0,10)||'0001',phase:1,label:'آخرین وضعیت چک قدیمی '+c.number+': '+checkStatuses[c.status]+' (مراحل قبلی ثبت نشده)',debit:0,credit:0,at:c.updatedAt,user:c.updatedBy,informational:true});for(const a of events.filter(a=>a.action==='update')){const change=a.changes.find(x=>x.field==='status');if(change)rows.push({date:a.at.slice(0,10),phase:0,label:'چک '+c.number+': '+checkStatuses[change.before]+' ← '+checkStatuses[change.after],debit:0,credit:0,at:a.at,user:a.user,informational:true})}}for(const x of state.payments.filter(x=>x.partyId===id)){const c=state.checks.find(c=>c.id===x.checkId);rows.push({date:x.date,phase:1,label:x.checkId?'تسویه از محل وصول چک '+(c?.number||''):(x.method==='bank'?'واریز / انتقال بانکی':x.method==='card'?'کارت‌خوان':x.method==='cash'?'دریافت / پرداخت نقدی':'دریافت / پرداخت قدیمی؛ روش نامشخص')+(x.note?' · '+x.note:''),debit:0,credit:x.amount,at:x.createdAt,user:x.createdBy})}rows.sort((a,b)=>a.date.localeCompare(b.date)||(a.at||'').localeCompare(b.at||'')||(a.phase||0)-(b.phase||0));let running=0;return rows.map(r=>({...r,balance:running+=r.debit-r.credit}))}
function ledger(id){const p=state.parties.find(p=>p.id===id),rows=ledgerEvents(id),html=`<h2>ریز حساب ${esc(p.name)}</h2><p style="margin:12px 0">${p.type==='customer'?'مانده مثبت: بدهی مشتری به شما':'مانده مثبت: طلب تأمین‌کننده از شما'} · مبالغ به ریال</p><div class="notice">دریافت چک از مانده کم می‌شود؛ وصول دوباره کسر نمی‌کند و برگشت چک بدهی را برمی‌گرداند. تاریخ سند و زمان ثبت جدا هستند. زمان و کاربر سوابق قدیمی ممکن است نامشخص باشد.</div>`+table(['تاریخ سند / رویداد','شرح گردش','افزایش مانده','کاهش مانده','مانده پس از گردش','زمان ثبت (تهران)','انجام‌دهنده'],rows.map(r=>`<tr class="${r.informational?'infoevent':''}"><td>${r.date==='0000'?'اول دوره':r.date==='0001'?'نامشخص':pdate(r.date)}</td><td class="ledgerdesc">${esc(r.label)}${r.informational?'<div class="sub">اطلاع‌رسانی؛ بدون اثر بر مانده</div>':''}</td><td>${fmt(r.debit)}</td><td>${fmt(r.credit)}</td><td><b>${fmt(r.balance)}</b></td><td>${esc(stampTime(r.at))}</td><td>${esc(actorName(r.user))}</td></tr>`).join(''))+`<div class="previewtotal">مانده نهایی: ${money(balance(id))}</div>`;show('ریز حساب کامل',`<div class="formbody ledgerwide">${html}<button class="btn primary" style="margin-top:22px" id="printLedger">چاپ ریز حساب کامل</button></div>`);$('#modal').classList.add('wide-dialog');$('#printLedger').onclick=()=>{$('#printarea').innerHTML=html;window.print()}}
function payments(){return title('دریافت و پرداخت','ثبت گردش وجه، روش پرداخت، کاربر و زمان هر مرحله.',`<button class="btn primary" onclick="paymentForm()">＋ ثبت تراکنش</button>`)+panel('گردش وجوه',table(['طرف حساب','روش','تاریخ سند','مبلغ','شرح','زمان و کاربر ثبت',''],[...state.payments].reverse().map(p=>`<tr><td>${esc(state.parties.find(x=>x.id===p.partyId)?.name)}</td><td>${p.checkId?'وصول چک':p.method==='bank'?'بانکی':p.method==='card'?'کارت‌خوان':p.method==='cash'?'نقدی':'قدیمی؛ روش نامشخص'}</td><td>${pdate(p.date)}</td><td>${money(p.amount)}</td><td>${esc(p.note)}</td><td>${esc(stampTime(p.createdAt))}<div class="sub">${esc(actorName(p.createdBy))}</div></td><td>${editAction('payments',p.id)} <button class="link" onclick="recordHistory('payments','${p.id}')">تاریخچه</button></td></tr>`).join('')))}
function checks(){return title('مدیریت چک‌ها','ثبت چک و پیگیری مراحل، با تاریخ، ساعت و انجام‌دهنده.',`<button class="btn primary" onclick="checkForm()">＋ چک جدید</button>`)+`<div class="notice">ثبت چک همان لحظه از حساب کم می‌شود؛ وصول دوباره اثر مالی ندارد و برگشت چک بدهی را برمی‌گرداند.</div>`+panel('دفتر چک‌ها',table(['شماره / بانک','طرف حساب','نوع','سررسید','مبلغ','وضعیت','آخرین تغییر / کاربر',''],state.checks.map(c=>`<tr><td>${esc(c.number)}<div class="sub">${esc(c.bank)}</div></td><td>${esc(state.parties.find(p=>p.id===c.partyId)?.name)}</td><td>${c.type==='received'?'دریافتی':'پرداختی'}</td><td>${pdate(c.date)}</td><td>${money(c.amount)}</td><td>${c.status==='cleared'?'<span class="badge ok">وصول شده</span>':`<select aria-label="وضعیت چک" onchange="changeCheck('${c.id}',this.value)"><option value="pending" ${c.status==='pending'?'selected':''}>در انتظار</option><option value="returned" ${c.status==='returned'?'selected':''}>برگشتی</option><option value="cleared">وصول شد</option></select>`}</td><td>${esc(stampTime(c.updatedAt))}<div class="sub">${esc(actorName(c.updatedBy))}</div></td><td>${editAction('checks',c.id)} <button class="link" onclick="recordHistory('checks','${c.id}')">تاریخچه مراحل</button></td></tr>`).join('')))}
function changeCheck(id,status){const c=state.checks.find(c=>c.id===id);if(!c||c.status===status||c.status==='cleared'||!checkStatuses[status])return render();if(status==='cleared'&&!confirm('وصول چک تأیید می‌شود؟ مبلغ دوباره از مانده کسر نمی‌شود.'))return render();if(commit(()=>{c.status=status;if(status==='cleared'&&!state.payments.some(p=>p.checkId===id))state.payments.push({id:uid(),partyId:c.partyId,amount:c.amount,date:day(),note:'وصول چک '+c.number,method:'check',checkId:id,...(c.invoiceId?{invoiceId:c.invoiceId}:{})})}))toast('مرحله چک با زمان و نام انجام‌دهنده ثبت شد.')}

function old041InvoiceLaterPaid(i){return state.payments.filter(p=>p.invoiceId===i.id).reduce((s,p)=>s+p.amount,0)}
function invoiceOutstanding(i){return total(i)-i.paid-invoiceLaterPaid(i)-state.returns.filter(r=>r.invoiceId===i.id).reduce((s,r)=>s+returnTotal(r)-r.paid,0)}
function demoSeed(){return normalizeData({schemaVersion:1,demo:true,products:[],parties:[],invoices:[],payments:[],checks:[],returns:[],groups:defaultGroups(),staff:[],audit:[]})}
function prepareSplitDemo(){if(localStorage.getItem(KEY))return;const d=day();commit(()=>state.products.push({id:'split-product',code:'DEMO-BL-01',name:'ساعت بلموند — نمونه آزمایشی',brand:'BELMOND',price:100000000,cost:70000000,opening:10}));commit(()=>state.parties.push({id:'split-customer',name:'مشتری آزمایشی — نقد و چک',phone:'',type:'customer',groupId:'g-customer',opening:0}));commit(()=>state.invoices.push({id:'split-invoice',number:'DEMO-F-1001',type:'sale',partyId:'split-customer',date:d,discount:0,paid:100000000,items:[{productId:'split-product',name:'ساعت بلموند — نمونه آزمایشی',code:'DEMO-BL-01',qty:2,price:100000000}]}));const due=new Date(d+'T12:00:00');due.setDate(due.getDate()+7);commit(()=>state.checks.push({id:'split-check',partyId:'split-customer',invoiceId:'split-invoice',number:'DEMO-CHECK-1001',bank:'بانک نمونه (آزمایشی)',amount:100000000,date:due.toISOString().slice(0,10),type:'received',status:'pending'}))}
function splitDemo(){const i=state.invoices.find(i=>i.id==='split-invoice'),c=state.checks.find(c=>c.id==='split-check');if(!i||!c)return title('نمونه تسویه ترکیبی','رکوردهای نمونه در این مرورگر تغییر کرده‌اند.')+`<button class="btn" onclick="location.href='/'">بازگشت به برنامه اصلی</button>`;const cleared=c.status==='cleared';return title('نمونه فروش؛ نصف نقد، نصف چک','فاکتور و مراحل زیر از قبل در این فضای کاری ثبت شده‌اند.',`<button class="btn" onclick="location.href='/'">برنامه اصلی ←</button>`)+`<div class="notice">این فضای نمونه، اطلاعات جدا از برنامه اصلی دارد. تمام کالاها، اشخاص، فاکتور و چک این صفحه ساختگی‌اند و هیچ پرداخت بانکی واقعی انجام نمی‌شود.</div><div class="stats"><div class="stat"><div class="stathead">مبلغ فاکتور</div><div class="value">${fmt(200000000)}<span class="unit">ریال</span></div><div class="sub">۲ ساعت × ۱۰۰ میلیون ریال</div></div><div class="stat"><div class="stathead">نصف نقدی؛ دریافت شده</div><div class="value">${fmt(100000000)}<span class="unit">ریال</span></div><span class="badge ok">ثبت شده</span></div><div class="stat"><div class="stathead">نصف چک</div><div class="value">${fmt(100000000)}<span class="unit">ریال</span></div><span class="badge ${cleared?'ok':'warn'}">${cleared?'وصول آزمایشی انجام شد':'در انتظار وصول'}</span></div><div class="stat"><div class="stathead">مانده حساب مشتری</div><div class="value">${fmt(balance('split-customer'))}<span class="unit">ریال</span></div><div class="sub">${cleared?'تسویه کامل؛ چک وصول شده':'تسویه با چک دریافت‌شده'}</div></div></div>`+panel('روند ثبت‌شده',`<div class="panelbody"><ol class="demosteps"><li><b>ثبت فاکتور فروش DEMO-F-1001</b><p>فروش ۲ ساعت؛ بدهی مشتری ۲۰۰ میلیون و موجودی از ۱۰ به ۸ عدد.</p><small>${esc(stampTime(i.createdAt))} · ${esc(actorName(i.createdBy))}</small></li><li><b>دریافت ۱۰۰ میلیون ریال نقدی</b><p>پرداخت هم‌زمان فاکتور؛ مانده مشتری ۱۰۰ میلیون ریال.</p><small>${esc(stampTime(i.createdAt))} · ${esc(actorName(i.createdBy))}</small></li><li><b>دریافت چک ۱۰۰ میلیون ریالی</b><p>چک DEMO-CHECK-1001 با سررسید ${pdate(c.date)}؛ تا قبل از وصول، مانده با دریافت چک صفر می‌شود؛ چک در انتظار وصول باقی می‌ماند.</p><small>${esc(stampTime(c.createdAt))} · ${esc(actorName(c.createdBy))}</small></li><li><b>${cleared?'وصول چک و تسویه کامل':'مرحله بعد: وصول چک'}</b><p>${cleared?'وصول چک ثبت شد؛ مانده دوباره کسر نشد.':'با دکمه زیر وصول را آزمایش کن؛ رویداد وصول ثبت می‌شود و مانده دوباره کاهش نمی‌یابد.'}</p>${cleared?`<small>${esc(stampTime(c.updatedAt))} · ${esc(actorName(c.updatedBy))}</small>`:`<button class="btn primary" onclick="simulateSplitClear()">شبیه‌سازی وصول چک و تسویه کامل</button>`}</li></ol><div class="actions" style="margin-top:22px"><button class="btn gold" onclick="ledger('split-customer')">دیدن ریز حساب کامل</button><button class="btn" onclick="viewInvoice('split-invoice')">مشاهده / چاپ فاکتور</button><button class="btn" onclick="recordHistory('checks','split-check')">تاریخچه چک</button><button class="btn" onclick="showCardex('split-product')">کاردکس کالا</button></div></div>`)}
function simulateSplitClear(){if(!DEMO_MODE)return;const c=state.checks.find(c=>c.id==='split-check');if(!c||c.status==='cleared')return;if(commit(()=>{c.status='cleared';state.payments.push({id:uid(),partyId:c.partyId,invoiceId:c.invoiceId,amount:c.amount,date:day(),note:'شبیه‌سازی وصول چک نمونه DEMO-CHECK-1001',method:'check',checkId:c.id})})){toast('وصول آزمایشی ثبت شد؛ مبلغ دوباره از حساب کسر نشد.')}}

function addMainExample(notify=true){const existing=state.invoices.find(i=>i.id==='main-example-invoice');if(existing){page='invoices';query='';render();return true}const ids=['main-example-product','main-example-customer','main-example-invoice','main-example-check'];if(Object.keys(entityNames).some(k=>state[k].some(r=>ids.includes(r.id)))){if(notify)toast('شناسه نمونه از قبل استفاده شده؛ اطلاعات موجود تغییر نکرد.');return false}const d=day(),due=new Date(d+'T12:00:00');due.setDate(due.getDate()+7);let number=1001;while(state.invoices.some(i=>i.number==='DEMO-F-'+number))number++;let code='DEMO-MAIN-BL-01',suffix=1;while(state.products.some(p=>p.code===code))code='DEMO-MAIN-BL-01-'+suffix++;let cheque='DEMO-MAIN-CHECK-1001';while(state.checks.some(c=>c.number===cheque))cheque+='-1';const ok=commit(()=>{let group=state.groups.find(g=>g.type==='customer');if(!group){group={id:uid(),name:'مشتریان آزمایشی',type:'customer'};state.groups.push(group)}state.products.push({id:ids[0],code,name:'ساعت بلموند — نمونه نقد و چک',brand:'BELMOND',price:100000000,cost:70000000,opening:10});state.parties.push({id:ids[1],name:'مشتری نمونه — نصف نقد / نصف چک',phone:'',type:'customer',groupId:group.id,opening:0});state.invoices.push({id:ids[2],number:'DEMO-F-'+number,type:'sale',partyId:ids[1],date:d,discount:0,paid:100000000,items:[{productId:ids[0],name:'ساعت بلموند — نمونه نقد و چک',code,qty:2,price:100000000}],isExample:true});state.checks.push({id:ids[3],partyId:ids[1],invoiceId:ids[2],number:cheque,bank:'بانک نمونه (آزمایشی)',amount:100000000,date:due.toISOString().slice(0,10),type:'received',status:'pending',isExample:true})});if(ok){page='invoices';query='';render();if(notify)toast('فاکتور نمونه داخل همین فهرست ثبت شد.')}return ok}
function mainExampleNotice(){const i=state.invoices.find(i=>i.id==='main-example-invoice');if(!i)return `<div class="notice">برای دیدن روند نصف نقد / نصف چک در همین فهرست، دکمه «ثبت فاکتور نمونه» را بزن. نمونه قبلی در فضای جدا بود.</div>`;const c=state.checks.find(c=>c.invoiceId===i.id);return `<div class="notice"><b>فاکتور آزمایشی ${esc(i.number)} در همین فهرست ثبت شده است.</b><br>${money(total(i))} فروش؛ ${money(i.paid)} نقدی و ${money(c?.amount||0)} چک ${c?.status==='cleared'?'وصول‌شده':'در انتظار وصول'}. مانده فعلی: ${money(invoiceOutstanding(i))}<div class="actions" style="margin-top:12px"><button class="btn small" onclick="viewInvoice('${i.id}')">باز کردن فاکتور نمونه</button><button class="btn small" onclick="ledger('${i.partyId}')">ریز حساب مشتری نمونه</button><button class="btn small" onclick="go('checks')">مشاهده چک نمونه</button></div></div>`}

