function usernameOf(input){const username=String(input||'').trim().normalize('NFKC').toLowerCase();if(!/^[a-z0-9_.-]{3,40}$/.test(username))fail('نام کاربری باید ۳ تا ۴۰ حرف انگلیسی، عدد، نقطه یا زیرخط باشد.');return username}
function normalizePin(p){return typeof p==='string'?p.replace(/[۰-۹]/g,c=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(c)).replace(/[٠-٩]/g,c=>'٠١٢٣٤٥٦٧٨٩'.indexOf(c)):p}
function checkPassword(p){p=normalizePin(p);if(typeof p!=='string'||!/^\d{4,6}$/.test(p))fail('رمز باید فقط عدد و بین ۴ تا ۶ رقم باشد.');return p}
